// Act IV, lot IV3: the road up the Fenne (r_fenne, region fenne), the glacier, the white dragon Ardhal, the act choice
// (purify, kill or bind him), and the interlude that leads down to the Sceau (V_route).
"use strict";
var ROUTE = "@route";
var H_PIP = { with: "pip", v: 10 }, H_COL = { with: "coliane", v: 10 }, H_THA = { with: "thavary", v: 10 },
  H_CHA = { with: "charline", v: 10 }, H_AUB = { with: "aubin", v: 10 }, H_GLO = { with: "gloup", v: 10 };
var H_CRAMPONS = { if: { item: "IVD_crampons" }, v: 10 }, H_FOURRURE = { if: { item: "IVD_fourrure" }, v: 5 },
  H_CORDE = { if: { item: "corde" }, v: 5 }, H_CARTE = { if: { item: "IVD_carte" }, v: 10 };
var P = {};

// ------------------------------------------------------------------ Vaux: the departure for the Fenne
Object.assign(P, {
  IVD_depart: { act: "IV", title: "Le chemin de la Fenne", place: "vaux", hub: true, backName: "le bout du camp, au pied du chemin de la Fenne",
    fx: { ep: ["seance", 1500], meet: "ardhal" },
    text: [
      { first: true, text: "Le camp de Vaux-Saint-Pierre finit là où finit la boue. Après les dernières tentes, après l'enclos où l'on parque les chèvres des réfugiés et la fosse où l'on brûle ce qui est mort de la fièvre grise, un chemin de mulets monte entre deux murets de pierres sèches, droit vers la montagne. Personne ne le prend plus. Les ornières sont pleines d'eau gelée, et l'herbe a repoussé au milieu." },
      { first: true, text: "Au-dessus, la Fenne. Tu l'as vue de loin tout l'automne, une muraille noire posée au bout de la vallée. D'ici, elle n'a plus rien d'une muraille : ce sont des pentes, des forêts de mélèzes qui s'arrêtent net, des éboulis gris, et plus haut, coincée entre deux crêtes comme une langue entre deux dents, la glace. Le glacier de la Fenne descend vers toi, bleu sale, strié de noir, et au bout, là où il se perd dans les nuages, il y a ce que les gens d'ici appellent l'antre, et qu'ils ne regardent pas en face." },
      { first: true, if: { has: "R:revele" }, text: "Tu sais maintenant ce qu'il y a sous cette glace. Un homme, un guérisseur, le plus jeune des six, qui tient une porte depuis quatre cents ans. Edrin te l'a dit à Hautecombe, de sa voix de vieillard aveugle, et depuis tu ne regardes plus la montagne de la même façon. On t'a appris à la craindre. Tu as envie de t'excuser auprès d'elle." },
      { first: true, if: { not: { has: "R:revele" } }, text: "Ce qu'il y a sous la glace, tu ne le sais qu'à moitié. Edrin, à Hautecombe, t'en a dit assez pour que tu cesses de croire l'histoire des bornes, pas assez pour que tu saches quoi croire à la place. Le dragon sait, disent ceux du camp. Le dragon a tout vu." },
      { first: true, if: { is: { maitre: "mort" } }, text: "Ta maîtresse ne verra pas cette montagne. Elle en parlait, autrefois, comme d'un livre qu'elle garderait pour ses vieux jours. Tu la portes avec toi, d'une certaine façon : sa façon de regarder un chemin avant de le prendre, que tu as sans t'en rendre compte." },
      { first: true, if: { is: { maitre: "perdu" } }, text: "Les ornières du chemin sont pleines d'une eau grise, gelée sur les bords. Tu ne la regardes pas. Depuis l'Isarde, tu ne regardes plus l'eau, de peur d'y voir un visage que tu connais, et qui te dirait ton nom avec deux voix." },
      { first: true, text: "Ardhal. Le vieux dragon blanc. Les chasseurs de la Fenne disent qu'il dort depuis cent ans au fond de son antre et qu'il ne descend plus. Ils disent aussi, depuis la Saint-Martin, qu'on l'a vu voler la nuit au-dessus du glacier, et que ses ailes n'étaient plus blanches." },
      { again: true, text: "Le chemin de mulets monte toujours entre ses deux murets, et le glacier, tout en haut, n'a pas bougé. Derrière toi, le camp fume sous la pluie : des feux de bois vert, des marmites, des enfants qui crient pour se réchauffer." },
      { with: "pip", text: "Pip regarde la glace en silence. Il ne brille presque pas. Quand tu lui demandes ce qu'il a, il répond qu'il a froid, ce qui ne lui arrive jamais, et qu'il ne sait pas pourquoi la montagne lui fait penser à une main fermée." },
      { with: "coliane", text: "Coliane resserre les lanières de ses bottes, l'une après l'autre, avec un soin exagéré. Elle n'aime pas la montagne. « On ne voit rien venir, là-haut, dit-elle. Ou alors on voit tout venir, de très loin, et on n'a nulle part où aller. »" },
      { with: "thavary", text: "Thavary a ciré son épée la veille au soir, longtemps, à la lueur du feu, comme on le fait avant les grandes choses. Elle regarde le glacier avec l'attention d'un capitaine qui compte les tours d'une place forte." },
      { with: "charline", text: "Charline a les mains dans ses manches et le nez rouge. « De la glace, dit-elle. Quatre lieues de glace, et un dragon de givre au bout. Moi qui fais du feu. » Elle a l'air presque contente." },
      { with: "aubin", text: "Frère Aubin a fait le signe de la Main en voyant la montagne, puis il s'est arrêté au milieu, comme quelqu'un qui ne sait plus très bien à qui il s'adresse." },
      { with: "gloup", text: "Gloup s'est roulé dans une flaque gelée, a poussé un petit cri, et s'est réfugié dans ta botte. Il n'avait jamais vu de glace." },
      { if: { mark: { min: 3 } }, text: "Ta main gauche te brûle depuis que tu regardes la montagne. La tache noire a dépassé le poignet. Quand tu fermes les yeux, tu entends de l'eau couler sous de la glace, très loin, et une voix qui fredonne." },
    ],
    choices: [
      { label: "La tente où l'on soigne ta maîtresse", hide: { not: { is: { maitre: "sauve" } } }, to: "IVD_maitre" },
      { label: "L'étal d'Ancelin le fourreur, sous sa bâche", to: "IVD_fourreur" },
      { label: "La femme qui attend au bout du chemin, chaque jour, depuis un mois", hide: { seen: "IVD_soeur" }, to: "IVD_soeur" },
      { label: "Rendre à Bastienne ce que tu rapportes de la montagne", hide: { any: [{ not: { seen: "IVD_soeur" } }, { not: { has: "pelerins:sort" } }, { seen: "IVD_soeur_retour" }] }, to: "IVD_soeur_retour" },
      { label: "Les deux cavaliers qui te cherchent dans le camp", hide: { any: [{ not: { is: { jeton: ["ordre", "deux"] } } }, { seen: "IVD_messagers" }] }, to: "IVD_messagers" },
      { label: "Le cavalier en manteau bleu qui te cherche dans le camp", hide: { any: [{ not: { is: { jeton: "cercle" } } }, { seen: "IVD_messagers" }] }, to: "IVD_messagers" },
      { label: "Le troll qui attend sous la pluie, à l'écart des tentes", hide: { any: [{ not: { has: "grauk:allie" } }, { seen: "IVD_troll" }] }, to: "IVD_troll" },
      { label: "Veiller une dernière nuit au camp, avec ceux qui partent", hide: { seen: "IVD_veillee" }, to: "IVD_veillee" },
      { label: "Prendre le chemin de la Fenne, vers le glacier", big: true, travel: "r_fenne" },
      { back: "IV_hub" },
    ] },

  IVD_maitre: { act: "IV", title: "La tente des malades", place: "vaux",
    text: [
      "On l'a mise dans la tente des sœurs grises, au fond, derrière un rideau de toile tendu sur une corde. Il fait plus chaud là qu'ailleurs : un brasero de fonte, des pierres chaudes enveloppées de laine au pied des paillasses. Ça sent le vinaigre, la sueur et la sauge.",
      { if: { has: "maitre:hauberte" }, text: "Hauberte est assise, le dos contre un coffre, une couverture sur les genoux. Elle a maigri depuis l'Isarde. La tache de son cou a pâli jusqu'à n'être plus qu'une ombre grise, comme une meurtrissure qui guérit, mais elle la cache encore sous un foulard. Elle essaie de se lever en te voyant. Tu l'en empêches. Elle te laisse faire, et c'est ce qui te fait le plus de peine." },
      { if: { has: "maitre:ortie" }, text: "Ortie est assise sur sa paillasse, les jambes repliées sous elle comme une jeune fille, et trie des herbes sèches dans un bol. Ses mains tremblent un peu. Les ongles sont encore gris, à la racine, mais ses yeux sont à elle, verts et vifs. Elle a déjà réorganisé toute la pharmacie des sœurs, qui ne savent pas si elles doivent la remercier." },
      { if: { has: "maitre:maelle" }, text: "Maëlle est assise à une table de camp, ses lunettes sur le nez, et dessine. Elle dessine la montagne, de mémoire, à la plume, avec une précision qui fait peur. Sa main gauche, posée à plat sur la feuille, est gantée de laine : elle ne l'enlève jamais. Quand elle lève la tête et qu'elle te voit, elle sourit, et le sourire tient un moment avant de retomber." },
      "« Tu montes, dit-elle. Je le vois à tes bottes. » Elle tend la main vers toi, et tu la prends. Elle a la main froide. « Écoute-moi bien, parce que je n'ai pas eu le temps de te le dire avant, et que j'ai cru longtemps que je ne te le dirais jamais. Ardhal n'est pas une bête. Il parle. Il pense plus lentement que nous et plus loin. Si tu montes là-haut avec l'idée de tuer une bête, tu redescendras avec un mort sur la conscience, et tu ne sauras même pas qui c'était. »",
      "Elle se tait un moment. « Elle me parlait de lui, tu sais. Dans l'eau. Quand j'étais à elle. Elle disait : il est presque à moi, le vieux blanc. Il ne lui manque qu'une main pour le tenir. » Elle serre ta main plus fort. « Ne sois pas cette main. »",
    ],
    choices: [
      { label: "« Qu'est-ce que tu sais d'autre sur lui ? »", to: "IVD_maitre_conseil" },
      { label: "« Repose-toi. Je reviendrai. »", fx: { conf: { pip: 3 } }, back: "IVD_depart" },
    ] },
  IVD_maitre_conseil: { act: "IV", title: "Ce que savait ta maîtresse", place: "vaux",
    fx: { item: "IVD_carte", ep: ["perso", 1200] },
    text: [
      "« Pas grand-chose de plus que les chasseurs, dit-elle. Mais je sais lire ce qu'ils racontent. » Elle tire de sous sa couverture un carré de parchemin plié en huit, taché d'eau, que tu reconnais : c'est le papier de ses cartes, celui qu'elle achetait à Ferrance par rames entières. « Je l'ai faite avant la chapelle. Avant tout ça. J'étais montée jusqu'au refuge, l'été d'avant. Je comptais aller plus haut. Je ne suis pas allée plus haut. »",
      "La carte montre le chemin de la Fenne, ses lacets, l'oratoire des pèlerins, le refuge des chasseurs, et au-delà, en traits plus légers, le glacier, les crevasses qu'elle a pu voir d'en bas, un col marqué d'une croix. Dans la marge, de sa petite écriture : *Le pont de glace ne tient que le matin.* Et plus bas, soulignée deux fois : *Ne pas boire l'eau de fonte sous l'antre. Celle de la grotte bleue, oui.*",
      { if: { has: "maitre:hauberte" }, text: "« Et une chose encore, dit Hauberte. Si tu dois te battre contre lui, ne te bats pas face à lui. Personne ne survit à un dragon face à lui. On se bat contre son flanc, sous l'aile, là où il ne peut pas tourner la tête. C'est ce qu'on m'a appris à l'Ordre, et c'est la seule chose que l'Ordre m'ait apprise qui était vraie. »" },
      { if: { has: "maitre:ortie" }, text: "« Et une chose encore, dit Ortie. La vase, sur une bête, ça se lave comme sur une plaie : de l'intérieur vers l'extérieur. Pas l'inverse. Si tu le laves, commence par les yeux. Les yeux, c'est par là qu'elle entre et par là qu'elle sort. »" },
      { if: { has: "maitre:maelle" }, text: "« Et une chose encore, dit Maëlle. Le glacier avance. Pas vite, mais il avance, et il ne pardonne pas qu'on l'oublie. Ce que tu vois le soir n'est pas tout à fait ce que tu verras le matin. Regarde toujours deux fois. »" },
      "Elle ferme les yeux. Elle est fatiguée ; elle a parlé plus qu'elle ne le fait d'habitude en un jour. Tu restes encore un peu, assis{e} au bord de la paillasse, jusqu'à ce que sa respiration devienne lente.",
    ],
    choices: [{ label: "La laisser dormir", back: "IVD_depart" }] },

  IVD_fourreur: { act: "IV", title: "L'étal d'Ancelin", place: "vaux", shop: "IVD_ancelin",
    fx: { meet: "IVD_ancelin" },
    text: [
      { first: true, text: "Sous une bâche tendue entre deux charrettes, Ancelin vend ce qu'il a sauvé de sa boutique de Sorbe-le-Haut avant que l'eau ne tourne : des peaux de mouton retournées, des moufles de feutre, des bonnets de loutre, des cordes de chanvre, et une caisse de crampons de fer qu'il appelle ses griffes. C'est un petit homme carré, la barbe en éventail, qui parle sans s'arrêter et compte encore plus vite qu'il ne parle." },
      { first: true, text: "« Vous montez, dit-il en te regardant les pieds. Tout le monde le voit, que vous montez. Avec ces semelles-là, vous ne passerez pas l'oratoire. Avec mes griffes, vous passerez le pont de glace, et peut-être même vous en reviendrez. Je ne promets pas la descente. Personne ne promet la descente. »" },
      { again: true, text: "Ancelin lève la tête de ses comptes. « Ah. Vous n'êtes pas encore mort{e}. C'est bon pour le commerce. »" },
      { if: { has: "passe:profite" }, text: "Il te regarde un peu trop longtemps, puis il dit : « Saint-Gilles-des-Prés. Vous êtes de là-bas, non ? J'avais un cousin, là-bas. Il a vendu sa terre pour rien, il y a sept ans, à quelqu'un qui passait. Il est mort à Sorbe-le-Haut cet été. » Il n'ajoute rien. Il ne sait pas. Ou il sait, et il vend quand même." },
      { if: { has: "passe:aide" }, text: "« Saint-Gilles, dit-il soudain. C'est vous qui portiez les malades au temple, l'année de la tache ? Ma sœur y était. Elle en est revenue. » Il pousse vers toi une paire de moufles. « Celles-là, vous ne les payez pas. Ne discutez pas, ça me ferait perdre du temps. »" },
    ],
    choices: [
      { label: "Accepter les moufles d'Ancelin", hide: { any: [{ not: { has: "passe:aide" } }, { has: "IVD:moufles" }] }, fx: { flag: "IVD:moufles", item: "IVD_fourrure" }, back: "IVD_depart" },
      { label: "Lui demander ce qu'on dit du dragon, à Sorbe-le-Haut", hide: { seen: "IVD_fourreur_dragon" }, to: "IVD_fourreur_dragon" },
      { back: "IVD_depart" },
    ] },
  IVD_fourreur_dragon: { act: "IV", title: "Ce qu'on dit du dragon", place: "vaux",
    text: [
      "Ancelin pose sa plume. Pour une fois, il prend le temps de chercher ses mots. « Chez nous, dit-il, on ne disait pas le dragon. On disait le Vieux. Le Vieux a pris trois moutons. Le Vieux a fait tomber la neige en juin. Quand j'étais petit, ma grand-mère laissait une écuelle de lait sur le muret, le soir de la Saint-Jean, pour le Vieux. Le matin, l'écuelle était vide. C'étaient les chats, bien sûr. »",
      "Il rajuste un bonnet sur la pile. « Ce printemps, des bergers de la haute Fenne sont descendus en disant que le Vieux avait tué tout leur troupeau, deux cents bêtes, et qu'il ne les avait pas mangées. Il les avait juste tuées, et laissées là, dans l'herbe, toutes noires. Les bergers ont dit qu'il pleurait en le faisant. » Il hausse les épaules. « Les bergers, ça boit. Mais ils ne pleuraient pas, eux, en le racontant. Ils avaient l'air de gens qui ont vu un ami devenir fou. »",
      { with: "coliane", text: "Coliane, derrière toi, dit à mi-voix : « J'ai connu des chiens comme ça. Quand la souillure les prend, ils mordent d'abord ceux qu'ils aiment. » Elle n'en dit pas plus." },
    ],
    choices: [{ label: "Le remercier", back: "IVD_fourreur" }] },

  // the sister of the pilgrim: side quest IVD_pelerins
  IVD_soeur: { act: "IV", title: "Bastienne", place: "vaux",
    fx: { meet: "IVD_bastienne", questSeen: "IVD_pelerins" },
    text: [
      "Elle est assise sur une borne au bord du chemin, à l'endroit exact où finissent les tentes, une couverture sur les épaules et un panier vide sur les genoux. Elle a peut-être trente ans, les joues rougies par le froid, les mains crevassées d'une lavandière. Elle regarde la montagne. On t'a dit qu'elle la regarde tous les jours, de l'aube au soir, depuis un mois.",
      "« Vous montez, dit-elle sans tourner la tête. On me l'a dit. » Puis elle te regarde. « Mon frère est monté, à la Toussaint. Gaspard. Avec les pèlerins de la Main, trente-deux, derrière un prêcheur de Ferrance qui disait que si on priait devant l'antre du Vieux, la montagne rendrait l'eau claire. Ils sont partis en chantant. On les a vus passer l'oratoire. Après, plus rien. Personne n'est redescendu. »",
      "Elle sort de son panier un petit objet enveloppé dans un linge : une médaille de la Main en étain, de celles qu'on vend aux pèlerins pour un denier, percée et pendue à un lacet. « Il avait la même. On les a achetées ensemble, à la foire de Sorbe, quand on était enfants. Si vous le trouvez... » Elle s'arrête. Elle ne sait pas comment finir sa phrase. Elle ne sait pas si elle veut qu'il soit vivant, ou seulement qu'on le lui dise.",
      { if: { has: "passe:fui" }, text: "Tu connais ce regard. Tu l'as vu, il y a sept ans, sur le visage de ceux qui restaient à Saint-Gilles et qui regardaient partir ceux qui partaient. Tu étais de ceux qui partaient. Elle, elle est de ceux qui attendent." },
    ],
    choices: [
      { label: "« Je le chercherai. »", fx: { conf: { aubin: 3, pip: 3 }, flag: "IVD:bastienne_promesse" }, to: "IVD_soeur_promesse" },
      { label: "« Je ne promets rien. Mais je regarderai. »", to: "IVD_soeur_promesse" },
    ] },
  IVD_soeur_promesse: { act: "IV", title: "La médaille", place: "vaux",
    text: [
      "Elle hoche la tête, comme si c'était ce qu'elle attendait et rien de plus. Elle ne te donne pas la médaille. Elle la garde serrée dans son poing, contre sa poitrine. « Il a une tache de vin sur la main droite, dit-elle. Là, entre le pouce et l'index. Il la cachait, petit. Il disait que c'était le diable qui l'avait mordu. » Elle a un rire bref. « Il n'a jamais cru au diable. Il croyait à la Main. Il croyait qu'en montant assez haut, on trouverait quelqu'un pour nous écouter. »",
      { with: "aubin", text: "Frère Aubin s'est approché. Il pose la main sur l'épaule de Bastienne, en silence, et elle ne la repousse pas. Quand il retire sa main, il a les lèvres serrées. Plus tard, sur le chemin, il te dira : « Des prêcheurs de Ferrance, j'en ai connu. Ils montent toujours en chantant. Ce n'est jamais eux qui portent les morts en redescendant. »" },
      "Quand tu t'éloignes, elle a repris sa place sur la borne, et regarde à nouveau la montagne.",
    ],
    choices: [{ back: "IVD_depart" }] },
  IVD_soeur_retour: { act: "IV", title: "Ce qu'on rapporte", place: "vaux",
    fx: { ep: ["perso", 1500], fac: { brumefeuille: 5 } },
    text: [
      "Bastienne est toujours là, sur sa borne. Elle te voit venir de loin, sur le chemin, et elle se lève. Elle ne court pas vers toi. Elle t'attend, debout, la couverture tombée à ses pieds dans la boue.",
      { if: { is: { pelerins: "sauve" } }, text: "Gaspard est déjà là, assis contre une tente, une écuelle de soupe entre les mains : les chasseurs du refuge l'ont descendu avant toi. Bastienne le regarde, puis te regarde. Elle ne dit pas merci. Elle prend ta main dans les deux siennes et la garde un moment, et c'est tout, et c'est beaucoup." },
      { if: { is: { pelerins: "paix" } }, text: "Tu lui tends la médaille de son frère, avec son lacet. Elle la prend, la regarde, la met à côté de la sienne dans le creux de sa main. Les deux médailles sont pareilles, usées pareil. « Il a eu froid ? » demande-t-elle. Tu lui dis la vérité : à la fin, non. Il ne parlait plus du froid. Il parlait d'elle. Elle hoche la tête, et elle s'assied sur la borne, et elle pleure enfin, comme on pose un sac trop lourd." },
      { if: { is: { pelerins: "laisse" } }, text: "Tu lui dis ce que tu as vu là-haut. Les trente-deux, la glace, et celui qui avait une tache de vin sur la main et qui n'a pas voulu redescendre. Elle t'écoute jusqu'au bout. Puis elle ramasse sa couverture, la secoue, et retourne vers les tentes en silence. Le lendemain, la borne est vide." },
    ],
    choices: [{ back: "IVD_depart" }] },

  // the messengers of the Order or of the Circle, according to the token
  IVD_messagers: { act: "IV", title: "Les messagers", place: "vaux",
    text: [
      { if: { is: { jeton: ["ordre", "deux"] } }, text: "Deux frères de l'Ordre, le gant gris à la ceinture, la boue jusqu'aux cuisses, attendent devant la tente où tu dors. Le plus âgé, un homme sec aux sourcils blancs, se présente : Frère Clotaire, de la commanderie du Val. Il a une lettre de Brann. Il ne la lâche qu'après avoir vu ton jeton de fer." },
      { if: { is: { jeton: ["ordre", "deux"] } }, text: "*« Le Grand Maître t'a parlé. Je ne sais pas tout ce qu'il t'a dit, et je ne veux pas le savoir par écrit. Je sais ce que je dois te demander. La bête de la Fenne a vu ce que nous avons fait. Elle se souvient. Si la souillure la prend, elle descendra, et elle parlera, et elle brûlera. Il n'y a qu'une façon d'être sûr. Je te le demande comme on demande une chose qu'on n'oserait pas faire soi-même. B. »*" },
      { if: { is: { jeton: ["cercle", "deux"] } }, text: "Un cavalier en manteau bleu t'aborde à la cantine, une jeune femme aux cheveux tirés, l'encre aux doigts, qui se présente comme Isolde de Rive, de l'Athénée. Elle te tend un pli au cercle brisé de Maître Corbin." },
      { if: { is: { jeton: ["cercle", "deux"] } }, text: "*« Ardhal est le dernier témoin vivant de la fondation du Sceau. Ce qu'il sait vaut plus que toutes nos bibliothèques. On dit que la souillure le ronge. Je ne te demande pas de le sauver : je ne sais pas si on le peut. Je te demande de l'écouter avant que quiconque ne le fasse taire. Et si tu peux, de m'écrire ce qu'il dit, mot pour mot. C. »*" },
      { if: { is: { jeton: "deux" } }, text: "Les deux messagers se croisent devant la cantine. Ils ne se saluent pas. Frère Clotaire regarde Isolde comme on regarde une tache sur une nappe, et Isolde regarde Frère Clotaire comme on regarde un livre qu'on a déjà lu et qu'on n'a pas aimé. Tu as dans ta besace deux jetons et deux lettres qui ne demandent pas la même chose." },
      { if: { has: "vendrel:demasque" }, text: "Le messager ajoute, à mi-voix, comme on dit une nouvelle de famille : « Le conseiller Vendrel n'a pas été retrouvé. On a fouillé Hautmont. Il s'est sauvé par les égouts, dit-on, ou par l'eau. Brann dit que c'est pareil. »", else: "On dit aussi au camp que Maître Vendrel est toujours au conseil d'Aldaran, et qu'il a fait envoyer à Vaux six charrettes de grain marquées de la tour d'argent, pour les réfugiés. On les a distribuées. On les a mangées. Personne n'a demandé d'où elles venaient." },
    ],
    choices: [
      { label: "Promettre à Brann ce qu'il demande", hide: { not: { is: { jeton: ["ordre", "deux"] } } }, fx: { flag: "IVD:promis_ordre", fac: { ordre: 10 } }, to: "IVD_messagers_fin" },
      { label: "Promettre à Corbin d'écouter le dragon", hide: { not: { is: { jeton: ["cercle", "deux"] } } }, fx: { flag: "IVD:promis_cercle", fac: { cercle: 10 }, item: "IVD_carnet" }, to: "IVD_messagers_fin" },
      { label: "Ne rien promettre à personne", to: "IVD_messagers_fin" },
    ] },
  IVD_messagers_fin: { act: "IV", title: "Les lettres pliées", place: "vaux",
    text: [
      { if: { has: "IVD:promis_ordre" }, text: "Frère Clotaire hoche la tête, une fois, et range la lettre de Brann dans son pourpoint. « Le sénéchal disait que tu le ferais. Il disait aussi qu'il préférerait que tu ne le fasses pas. Je n'ai pas compris. » Il remonte en selle. Il redescendra vers le Val dès demain, avec ta réponse." },
      { if: { has: "IVD:promis_cercle" }, text: "Isolde te donne un carnet neuf, relié de toile, et un crayon de plomb. « Mot pour mot, dit-elle. Même ce qui n'a pas de sens. Surtout ce qui n'a pas de sens. » Elle a l'air, en disant cela, d'avoir plus peur pour le carnet que pour toi." },
      { if: { all: [{ not: { has: "IVD:promis_ordre" } }, { not: { has: "IVD:promis_cercle" } }] }, text: "Tu replies les lettres et tu les rends. Tu n'as rien promis. Ceux qui les ont apportées s'en vont sans cacher leur déception. Tu montes vers un dragon qui a vu ce que personne n'a vu, et tu ne veux pas monter avec la réponse déjà écrite." },
      { with: "thavary", text: "Thavary te regarde faire, les bras croisés. « Une promesse, c'est une dette, dit-elle. Tu le sais. On la paie même quand on a changé d'avis. Surtout là. »" },
    ],
    choices: [{ back: "IVD_depart" }] },

  // Grauk's troll, if the king of the trolls is an ally
  IVD_troll: { act: "IV", title: "Le messager de Grauk", place: "vaux",
    fx: { item: "IVD_cor_grauk", ep: ["perso", 1000] },
    text: [
      "Les réfugiés se sont écartés de lui sur cinquante pas, et les enfants le regardent de loin, en se cachant derrière leurs mères. Il est assis sur un rocher sous la pluie, gris comme le rocher, aussi large, et il mange une rave crue avec beaucoup de délicatesse. Quand il te voit, il se lève, et il est deux fois plus grand que la tente la plus haute du camp.",
      "« Grauk dit, commence-t-il, d'une voix qui fait trembler les flaques. Grauk dit : le petit humain qui est descendu sous mon château, et qui en est remonté, il monte chez le Vieux. Grauk dit : le Vieux et Grauk, ça fait longtemps. Le Vieux a mangé le grand-père de Grauk. Grauk ne lui en veut pas. Le grand-père de Grauk était bête. » Il fouille dans sa besace, qui est une couverture de cheval nouée aux quatre coins, et en sort un cor taillé dans une corne de bouquetin, long comme ton bras. « Grauk dit : souffle dedans, là-haut, si ça va mal. Les trolls de Grauk sont dans la montagne. Ils viendront. Pas vite. Mais ils viendront. »",
      { with: "pip", text: "Pip va se poser sur le nez du troll, qui louche pour le regarder. « Bonjour », dit Pip. Le troll réfléchit longtemps. « Bonjour », dit-il enfin, très doucement, comme s'il avait peur de le casser." },
      "Il repart sous la pluie, sans se retourner, vers l'est, à grands pas, et les réfugiés le regardent disparaître entre les mélèzes. Le cor pèse lourd dans tes mains. Il sent la chèvre et la fumée.",
    ],
    choices: [{ back: "IVD_depart" }] },

  // the last night at the camp before the road
  IVD_veillee: { act: "IV", title: "La dernière nuit à Vaux", place: "vaux", takes: "night",
    fx: { rest: true, ep: ["perso", 1000] },
    text: [
      "Vous faites votre feu à l'écart, au pied du chemin, sur une plate-forme de pierres sèches où les muletiers d'autrefois chargeaient leurs bêtes. La pluie a cessé. Le ciel s'est ouvert au-dessus de la Fenne, et le glacier, sous la lune, luit d'une lumière pâle qu'il semble garder pour lui.",
      { if: { is: { berthe: ["sauvee", "cachee"] } }, text: "Une silhouette courbée monte vers vous depuis les tentes, avec une lanterne et un panier. C'est Berthe, la vieille de Brumefeuille, qui est venue jusqu'ici avec ses chèvres quand l'eau a tourné. Elle pose devant toi un fromage enveloppé dans une feuille de chou et une paire de chaussettes de laine qu'elle a tricotées. « Pour là-haut, dit-elle. Les pieds, c'est ce qui gèle en premier. Après, c'est la tête. » Elle repart sans s'asseoir." },
      { if: { is: { berthe: "pendue" } }, text: "Quelqu'un, dans le camp, chante une chanson de Brumefeuille, une chanson de lavoir. Tu la connais : tu l'as entendue fredonner une fois, par une vieille femme à qui les enfants jetaient des pierres. Elle n'est pas ici. Elle n'est plus nulle part. La chanson s'arrête au milieu d'un couplet, et personne ne la reprend." },
      { if: { is: { meunier: "livre" } }, text: "Au feu voisin, on parle de Brumefeuille. Le meunier Barthélemy a été jugé à Sorbe, dit-on, et banni de la vallée, et il a pris la route de l'est avec les autres. Personne n'a voulu camper près de lui. On l'a vu repartir vers Hautecombe, un matin, sans attendre la soupe." },
      { if: { is: { meunier: "protege" } }, text: "Au feu voisin, on parle de Brumefeuille, et d'un meunier qui a traversé le camp avec un sac pour tout bagage, en demandant où l'on manquait de bras. Il ne parlait à personne. Il passait ses nuits à regarder l'eau des abreuvoirs. Il est monté à Hautecombe avec les porteurs d'eau." },
      { if: { is: { meunier: "marche" } }, text: "Tu as rêvé de Margot, la nuit dernière. Une petite fille de neuf ans, mouillée, qui te tenait la main et t'appelait par ton nom. Tu n'as jamais vu son visage. Dans le rêve, tu le voyais." },
      { if: { is: { bucheron: ["soigne", "ramene"] } }, text: "Un garçon maigre aux cheveux coupés court vient te saluer, timide, et repart aussitôt : Tiennot, le fils du bûcheron du Rouvre, que tu as ramené de la forêt à l'automne. Il porte du bois pour les sœurs grises. Ses manches lui arrivent au milieu de l'avant-bras." },
      { if: { has: "nerys:lue" }, text: "Un colporteur venu du nord dit qu'à Hautmont, la princesse Nerys siège maintenant au conseil, à la place qu'occupait le premier conseiller, et que le vieux roi l'écoute. Il le dit comme une rumeur. Tu sais que c'en est un peu plus qu'une." },
      { if: { is: { gloup_arc: "eau" } }, text: "Il manque quelqu'un, ce soir, au bord du feu : une petite chose de bave qui aimait les chansons. Gloup est retourné à l'eau, à la tour. Tu as pris l'habitude de regarder tes bottes avant de les enfiler. Il n'y est plus." },
      { if: { has: "lune:remede" }, text: "Lune l'herboriste, qui soigne la fièvre grise sous une tente de Vaux depuis trois semaines, t'a fait porter un pot d'onguent et un mot : *Pour les engelures. Et pour le reste, ce qui peut se soigner.*" },
      { if: { is: { couronne: "paix" } }, text: "On boit, autour des feux, un vin aigre de Vel-Orin dans des gobelets d'Aldaran. Ça fait rire les réfugiés : c'est la paix, disent-ils, la paix, c'est quand on a les deux et qu'on n'a rien. Ce n'est pas tout à fait faux. C'est mieux que le contraire." },
      { if: { is: { couronne: "aldaran" } }, text: "Des piquiers d'Aldaran gardent les réserves de grain du camp. Ils sont polis, ils sont propres, et ils comptent chaque sac. On t'a dit que le roi Aldric voulait que la Sorbe sache qui la nourrissait. La Sorbe le sait. Elle se tait." },
      { if: { is: { couronne: "velorin" } }, text: "Les agents de la duchesse Orsini ont ouvert un comptoir à l'entrée du camp, où l'on échange les terres de la Sorbe contre du pain. Les réfugiés font la queue. Personne ne lit ce qu'il signe." },
    ],
    choices: [
      { label: "Laisser le feu parler", to: "IVD_veillee_feu" },
    ] },
  IVD_veillee_feu: { act: "IV", title: "Autour du feu", place: "vaux",
    text: [
      "Le feu craque. Personne n'a envie de dormir. On parle de ce qui vous attend là-haut, puis on cesse d'en parler, parce qu'on n'en sait rien.",
      { with: "coliane", if: { is: { coliane_arc: "justice" } }, text: "Coliane fait tourner entre ses doigts un des couteaux de Josse, qu'elle a gardé. « Je l'ai livré, dit-elle. À ceux qui jugent. J'ai cru que ça me ferait du bien. Ça ne m'a rien fait. Ça m'a juste laissé les mains libres. » Elle range le couteau. « C'est déjà ça. »" },
      { with: "coliane", if: { is: { coliane_arc: "vengeance" } }, text: "Coliane ne parle pas de Josse. Elle a lavé ses couteaux trois fois depuis, dans trois eaux différentes. Elle les lave encore ce soir, à la neige." },
      { with: "coliane", if: { is: { coliane_arc: "pitie" } }, text: "Coliane regarde le feu. « Il pleurait, dit-elle tout à coup. Josse. Quand je l'ai laissé partir. Il pleurait comme quand on était petits et que mon frère le battait à la lutte. » Elle hausse les épaules. « Je ne sais pas si j'ai bien fait. Je ne le saurai jamais. C'est ça, la pitié, je crois. »" },
      { with: "coliane", if: { all: [{ not: { is: { coliane_arc: ["justice", "vengeance", "pitie"] } } }, { has: "josse=reconnu" }] }, text: "Coliane regarde vers le bout du camp, là où campe ce qui reste des gens du Cercle. Elle ne dit pas le nom de Josse. Elle n'a pas besoin de le dire : ses mains le disent pour elle, à force de se serrer." },
      { with: "charline", if: { is: { charline_arc: "forge" } }, text: "Charline a les mains tendues vers le feu, mais c'est elle qui le nourrit : de petites flammes bleues lui sortent du bout des doigts et vont lécher les bûches. « Mon père m'a montré, dit-elle. À la tour. Comment on tient le feu sans le serrer. Il ne m'avait jamais rien montré. »" },
      { with: "charline", if: { is: { charline_arc: "brule" } }, text: "Charline ne fait pas de feu ce soir. Elle laisse les autres s'en occuper. Elle a les mains dans les manches et les yeux fixés sur la braise, et quand une bûche s'effondre en gerbe d'étincelles, elle ne bouge pas." },
      { with: "charline", if: { is: { charline_arc: "pardon" } }, text: "Charline écrit une lettre à son père, à la lueur du feu, en appuyant sur son genou. Elle en est à la troisième page. « Il ne pourra pas la lire tout seul, dit-elle. Ses mains. Il faudra que quelqu'un la lui tienne. » Elle continue d'écrire." },
      { with: "aubin", if: { is: { aubin_arc: "pretre" } }, text: "Frère Aubin dit les complies, à voix basse, pour personne et pour tout le monde. Tu ne l'avais pas entendu prier depuis la chapelle noyée. Sa voix est rouillée. Elle tient." },
      { with: "aubin", if: { is: { aubin_arc: "quitte" } }, text: "Aubin n'a plus l'habit. Il porte une veste de berger qu'il a échangée contre sa bure, et il a l'air d'un homme ordinaire, ce qui le surprend lui-même. « Je croyais que j'aurais froid, dit-il. Sans l'habit. Je n'ai pas plus froid. »" },
      { with: "aubin", if: { is: { aubin_arc: "offrande" } }, text: "Aubin regarde le glacier. Il ne le quitte pas des yeux de toute la soirée. Quand tu lui demandes à quoi il pense, il répond : « À ce qu'il y a dessous. À qui devrait y être. » Tu ne lui demandes pas qui." },
      { with: "thavary", if: { is: { thavary_arc: "honneur" } }, text: "Thavary dit, sans qu'on lui ait rien demandé, que sa grand-mère lui a écrit. Que le verger de Thavar a donné des pommes cette année, pour la première fois depuis longtemps. Elle n'en dit pas plus. Elle a l'air de quelqu'un qui a payé une dette et qui découvre qu'on respire mieux après." },
      { with: "thavary", if: { is: { thavary_arc: "vengeance" } }, text: "Thavary affûte son épée. Elle l'a affûtée hier. Elle l'affûtera demain. Le bruit de la pierre sur l'acier accompagne toute la veillée, régulier, et personne ne lui demande d'arrêter." },
      { with: "thavary", if: { is: { thavary_arc: "liberee" } }, text: "Thavary a défait ses tresses. Elle n'a plus l'air d'une chevalière, ce soir. Elle a l'air d'une femme de trente ans qui a froid et qui rit d'une plaisanterie de Pip. Elle remarque que tu la regardes, et elle ne refait pas ses tresses." },
      { with: "gloup", if: { is: { gloup_arc: "propre" } }, text: "Gloup, propre et presque transparent depuis la tour, se tient au bord du feu et regarde les flammes à travers lui-même. Il a encore un peu peur du feu. Moins." },
      { with: "gloup", if: { is: { gloup_arc: "lui" } }, text: "Gloup s'est installé sur ta botte, gris et collant comme au premier jour, et chante une chanson sans paroles qu'il a apprise on ne sait où. Il chante faux. Il chante content." },
      { with: "pip", text: "Pip s'est posé sur ton genou. « Tu crois qu'il se souvient de tout, le dragon ? demande-t-il. Même de ce qu'il voudrait oublier ? » Tu ne sais pas. Pip non plus. « Moi, je voudrais me souvenir, dit-il. Même de ce qui fait mal. »" },
      { without: "any", text: "Tu es seul{e} au bord du feu. C'est peut-être mieux ainsi : il n'y a personne à qui mentir sur ce que tu ressens en regardant la montagne." },
      "Tard dans la nuit, quand le feu n'est plus que braise, un grondement roule depuis le glacier, long, sourd, comme un orage qui serait sous la terre. Le camp entier se tait. Puis les chiens recommencent à aboyer, et les enfants à pleurer, et la nuit reprend.",
    ],
    choices: [{ label: "Dormir un peu avant l'aube", back: "IVD_depart" }] },
});

// ------------------------------------------------------------------ the road up the Fenne (r_fenne): legs
Object.assign(P, {
  // step 1: the pilgrims' oratory
  IVD_L_oratoire: { act: "IV", title: "L'oratoire des pèlerins", place: null,
    text: [
      "Le chemin de mulets s'arrête au dernier mélèze, à un oratoire de pierres sèches haut comme un homme, couvert de lauzes. À l'intérieur, sur une tablette, une main de bois peinte, paume ouverte, et autour d'elle des ex-voto de toutes les époques : des béquilles, des tresses de cheveux, des fers à cheval, des petits cœurs de cire fondus et refondus par cent étés. Les plus récents sont en dessous, à même le sol : des chapelets de pèlerins, encore brillants.",
      "Sur le mur de droite, quelqu'un a gravé des noms au couteau, frais, la pierre encore blanche dans les entailles. Trente-deux noms, sur quatre colonnes, et en haut, plus gros que les autres : *NICAISE DE FERRANCE, PRÊCHEUR, ET CEUX QUI L'ONT SUIVI. QUE LA MONTAGNE NOUS ENTENDE.*",
      "Au-dessus de la main de bois, dans le linteau, il y a cinq mains sculptées dans la pierre, très usées. Et une sixième. Personne ne l'a martelée, celle-ci. Elle est simplement plus petite que les autres, un peu à l'écart, comme un enfant qui suit des grands.",
      { if: { has: "passe:libre" }, text: "Tu as passé des cols comme celui-ci, avant, pour des contrats d'un jour, des marchands à escorter, des lettres à porter. Tu as toujours laissé quelque chose aux oratoires, un sou, un bout de pain. Pas par piété. Par politesse envers la montagne." },
      { with: "pip", text: "Pip s'est arrêté devant la sixième main. Il la regarde longtemps, de tout près, en silence, et quand tu l'appelles il sursaute comme quelqu'un qu'on réveille." },
    ],
    choices: [
      { label: "Chercher le nom de Gaspard parmi les trente-deux", hide: { not: { seen: "IVD_soeur" } }, to: "IVD_L_oratoire_noms" },
      { label: "Laisser un sou sur la tablette, pour ceux qui sont montés", if: { gold: { min: 1 } }, why: "Tu n'as pas un sou à laisser.", fx: { gold: -1, conf: { aubin: 3 }, flag: "IVD:obole" }, to: "IVD_L_oratoire_obole" },
      { label: "Reprendre la route", back: ROUTE },
    ] },
  IVD_L_oratoire_noms: { act: "IV", title: "Les trente-deux", place: null,
    text: [
      "Tu lis les noms un par un, du doigt, comme on lit un registre de baptêmes. Des noms de la Sorbe, des noms de Ferrance, deux noms de Merle. Une Jeanne, trois Pierre. Un enfant, sans doute, dont le nom est gravé plus bas que les autres et plus maladroitement, comme s'il l'avait fait lui-même : *TIBAUT, 9 ANS.*",
      "Le vingt-septième nom est *GASPARD DE SORBE-LE-HAUT.* Le G est tracé avec soin, presque calligraphié. On a pris le temps. On croyait revenir le relire.",
      { with: "aubin", text: "Frère Aubin dit à mi-voix les trente-deux noms, un par un, de la même voix égale, celle des offices des morts. Tu ne l'arrêtes pas. Ça prend un moment. Le vent se lève pendant qu'il lit." },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  IVD_L_oratoire_obole: { act: "IV", title: "Le sou sur la tablette", place: null,
    text: [
      "Ton sou tinte sur la tablette, à côté des chapelets. C'est peu. C'est ce que laissaient les muletiers d'autrefois, avant de prendre le col, pour que la montagne se souvienne d'eux s'ils n'en revenaient pas.",
      "Quand tu te retournes pour partir, le vent fait tourner lentement la main de bois sur son clou, paume vers toi.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  // step 2: the avalanche
  IVD_L_avalanche: { act: "IV", title: "La coulée", place: null, urgent: 20,
    text: [
      "Vous traversez une grande pente de neige, en écharpe, au-dessus d'une combe. La neige est lourde, croûtée, elle craque sous les pas avec un bruit de pain. À mi-pente, tu entends un autre craquement, plus sec, plus long, au-dessus de toi. Comme une branche qui casse. Mais il n'y a pas de branche.",
      "Tu lèves la tête. Toute la corniche, là-haut, cent pas de long, vient de se détacher d'un bloc, et descend. D'abord lentement, comme un drap qui glisse d'une table. Puis plus du tout lentement. Un nuage blanc monte devant elle, et un bruit qui grossit, qui grossit, et qui remplit tout.",
      { with: "any", text: "Quelqu'un crie ton nom. Tu ne sais pas qui." },
    ],
    choices: [
      { label: "Courir vers les rochers, en travers de la pente", test: { dom: "nature", diff: -10, label: "Fuir la coulée", help: [H_CRAMPONS, H_COL] },
        win: { fx: { ep: ["perso", 1200] }, to: "IVD_L_aval_abri" }, lose: { to: "IVD_L_aval_enseveli" } },
      { label: "« Derrière moi ! » crie Charline, les mains levées vers la neige", who: "charline", test: { dom: "magie", diff: 0, label: "Fendre la coulée par le feu" },
        win: { fx: { conf: { charline: 8 }, ep: ["perso", 1500] }, to: "IVD_L_aval_feu" }, lose: { fx: { conf: { charline: 2 } }, to: "IVD_L_aval_enseveli" } },
      { label: "Thavary t'empoigne par le col et te jette sous le surplomb", who: "thavary", test: { dom: "combat", diff: 0, label: "Thavary te tire à l'abri" },
        win: { fx: { conf: { thavary: 8 }, ep: ["perso", 1500] }, to: "IVD_L_aval_abri" }, lose: { to: "IVD_L_aval_enseveli" } },
      { label: "Te jeter à plat ventre, les bras sur la tête", timeout: true, to: "IVD_L_aval_enseveli" },
    ] },
  IVD_L_aval_feu: { act: "IV", title: "Le feu dans la neige", place: null,
    text: [
      "Charline ne recule pas. Elle plante ses pieds dans la neige, écarte les mains, et quelque chose sort d'elle que tu n'avais jamais vu : pas une flamme, une chaleur, une vague de chaleur blanche, qui frappe la coulée de face. La neige, devant vous, devient de l'eau, puis de la vapeur, dans un sifflement qui couvre le grondement. La coulée se fend en deux comme un flot contre une pile de pont, et passe de chaque côté de vous, à trois pas, en vous couvrant de neige mouillée.",
      "Quand le bruit s'arrête, vous êtes debout sur un îlot de rocher noir, fumant, au milieu d'une pente blanche et lisse. Charline tombe assise. Elle a le nez qui saigne et les mains rouges jusqu'aux coudes, et elle rit, d'un rire qui tremble. « Mon père, dit-elle, mon père n'aurait jamais... » Elle ne finit pas sa phrase. Elle n'a pas besoin.",
      { with: "pip", text: "Pip tourne autour de Charline, très vite, en brillant de toutes ses forces. Elle le laisse faire." },
    ],
    choices: [{ label: "Regarder ce que la coulée a mis au jour", to: "IVD_L_aval_fin" }] },
  IVD_L_aval_abri: { act: "IV", title: "Sous le surplomb", place: null,
    text: [
      "Tu atteins les rochers au moment où le nuage blanc les atteint aussi. Tu te jettes sous un surplomb de schiste, le nez dans la pierre, et la coulée passe au-dessus de toi, à côté de toi, partout, avec un bruit de tonnerre qui ne finit pas. La neige s'engouffre sous le rocher, te recouvre les jambes, le dos, et s'arrête.",
      { with: "thavary", text: "Thavary est tombée sur toi, de tout son poids, pour te garder sous la pierre. Quand le silence revient, elle se relève, se secoue, et dit seulement : « Tu me dois une cape. La mienne est restée là-haut. »" },
      "Puis le silence. Un silence total, épais, où tu entends ton cœur. Tu te dégages en rampant. Le soleil est revenu. La pente, devant toi, est lisse comme une nappe.",
    ],
    choices: [{ label: "Regarder ce que la coulée a mis au jour", to: "IVD_L_aval_fin" }] },
  IVD_L_aval_enseveli: { act: "IV", title: "Sous la neige", place: null,
    fx: { pv: -6 },
    text: [
      "La coulée te prend par les jambes, te soulève, te roule. Tu ne sais plus où est le haut. Tu as de la neige dans la bouche, dans les yeux, dans les oreilles. Puis tout s'arrête, d'un coup, et la neige durcit autour de toi comme du plâtre. Tu ne peux plus bouger que les doigts d'une main. Tu respires dans une petite poche d'air que ton visage a creusée. Il fait bleu, et très calme.",
      { with: "any", text: "Tu entends, très loin, au-dessus, des voix qui crient ton nom, et des coups sourds. On creuse. On creuse mal, au mauvais endroit, puis au bon. Une main gantée crève la neige au-dessus de ton visage, et la lumière entre, et l'air." },
      { with: "coliane", text: "C'est Coliane. Elle a les ongles en sang et ne s'en est pas aperçue. Elle te tire par le col, sans douceur, et quand tu es dehors, elle te frappe à l'épaule, deux fois, fort. « Ne refais jamais ça », dit-elle. Tu ne sais pas ce que tu as fait." },
      { with: "gloup", text: "C'est Gloup qui t'a trouvé{e}. Il s'est glissé dans la neige comme dans de l'eau, en suivant ta chaleur, et il est venu se coller contre ta joue en couinant, jusqu'à ce que les autres comprennent où creuser." },
      { without: "any", text: "Personne ne viendra. Tu le sais. Tu bouges les doigts. Puis la main. Puis tu creuses, vers ce que tu crois être le haut, en crachant la neige, en comptant, en t'arrêtant pour respirer, pendant un temps que tu ne sauras jamais mesurer. Ta main finit par crever la croûte. L'air froid te brûle les doigts. Tu ris tout seul{e}, la tête dans un trou." },
    ],
    choices: [{ label: "Reprendre ton souffle, et regarder autour de toi", to: "IVD_L_aval_fin" }] },
  IVD_L_aval_fin: { act: "IV", title: "Ce que la neige a découvert", place: null,
    fx: { flag: "IVD:avalanche" },
    text: [
      "La coulée a raboté la pente jusqu'à la vieille glace. Au milieu de la combe, à moitié dégagé, il y a un sac de pèlerin en toile grise, déchiré, et autour de lui, éparpillés sur la neige, des feuillets de psautier, un quignon de pain gelé dur comme une pierre, et une gourde de cuir. La gourde est pleine. Quand tu la débouches, il en coule un filet d'eau noire et tiède, qui fume dans le froid.",
      "Plus haut, au bord de la corniche arrachée, tu vois des traces dans la neige fraîche. De grandes traces, trois doigts griffus, profondes, espacées comme les pas d'un animal qui aurait la taille d'une grange. Elles vont jusqu'au bord, et s'arrêtent. Là où elles s'arrêtent, la neige a été balayée en éventail, comme sous un coup d'aile.",
      { with: "coliane", text: "Coliane regarde longtemps les traces. « Il était là-haut, dit-elle. Il nous regardait passer. Et la corniche est tombée. » Elle ne dit pas qu'il l'a fait tomber. Elle ne dit pas le contraire." },
      { with: "pip", text: "« Il ne voulait pas, dit Pip. Je crois. Je crois qu'il ne voulait pas et qu'il l'a fait quand même. » Il ne sait pas pourquoi il le croit." },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  // step 3: the hunters' refuge (side quest IVD_refuge)
  IVD_L_refuge: { act: "IV", title: "Le refuge des chasseurs", place: null, takes: "evening",
    fx: { meet: ["IVD_firmin", "IVD_joachim"], questSeen: "IVD_refuge" },
    text: [
      "Le refuge des chasseurs est une cabane de pierres basses, à demi enterrée dans la pente, avec un toit de lauzes chargé de grosses pierres contre le vent et une porte si basse qu'il faut se plier en deux. De la fumée sort par un trou du toit. Devant la porte, des peaux de chamois sèchent sur des perches, raides comme des planches, et deux chiens gris se lèvent sans aboyer.",
      "À l'intérieur, une seule pièce, un foyer au milieu, des bat-flanc contre les murs. Quatre chasseurs, des hommes de la haute Fenne aux visages tannés, aux barbes givrées, qui te regardent entrer sans se lever. Le plus vieux est assis au bord d'un bat-flanc, et sur le bat-flanc, sous trois couvertures, il y a un garçon de quinze ans qui tremble.",
      "« Firmin Fermaud, dit le vieux. Le refuge est à tout le monde. Mettez-vous au feu. » Il ne te regarde pas. Il regarde le garçon. « Mon fils, Joachim. Un bouquetin gris l'a pris à la cuisse, il y a quatre jours, au-dessus des séracs. Un bouquetin. Ça ne mord pas, un bouquetin. Celui-là mordait. »",
      "Le garçon a la jambe bandée. Les bandages sont noirs. Sous la peau du cou, des veines sombres montent vers la mâchoire, fines comme des racines, et ses yeux, quand il les ouvre pour te regarder, ont le blanc qui grisaille. Il sourit quand même. « Bonsoir, dit-il. Vous montez chez le Vieux ? Moi aussi, je voulais. »",
      { if: { has: "passe:aide" }, text: "Tu connais cette couleur de peau. Tu l'as vue sur des dizaines de visages, à Saint-Gilles, il y a sept ans, dans le temple plein. Tu sais combien de jours il reste quand les veines atteignent la mâchoire. Tu ne le dis pas." },
      { with: "aubin", text: "Frère Aubin s'est déjà agenouillé près du bat-flanc. Il ne demande la permission à personne. Il soulève la couverture, regarde la jambe, et la recouvre doucement." },
    ],
    choices: [
      { label: "Laver la plaie avec ta fiole d'eau claire", hide: { not: { item: "eau_claire" } }, fx: { drop: "eau_claire", set: { refuge: "gueri" }, flag: ["refuge:sort", "IVD:refuge_eau"], quest: "IVD_refuge", ep: ["seance", 3000], conf: { pip: 8, aubin: 5, coliane: 5 }, regard: { IVD_firmin: "redevable" } }, to: "IVD_refuge_gueri" },
      { label: "« Laisse-moi le veiller cette nuit », dit Frère Aubin", who: "aubin", hide: { has: "IVD:aubin_echec" }, test: { dom: "magie", diff: -10, label: "Aubin prie sur la plaie", help: [H_PIP] },
        win: { fx: { set: { refuge: "gueri" }, flag: ["refuge:sort", "IVD:refuge_aubin"], quest: "IVD_refuge", ep: ["seance", 3000], conf: { aubin: 10 }, regard: { IVD_firmin: "redevable" } }, to: "IVD_refuge_gueri" },
        lose: { fx: { flag: "IVD:aubin_echec" }, to: "IVD_refuge_aubin_echec" } },
      { label: "Poser ta main tachée sur la plaie, et prendre la souillure en toi", tag: "Marque +1", stain: true, fx: { mark: 1, set: { refuge: "marque" }, flag: "refuge:sort", quest: "IVD_refuge", ep: ["seance", 2500], conf: { coliane: -8, aubin: -5 }, fear: { coliane: 5 }, regard: { IVD_firmin: "craintif" } }, to: "IVD_refuge_marque" },
      { label: "Lui demander ce qu'il veut, lui", to: "IVD_refuge_joachim" },
    ] },
  IVD_refuge_aubin_echec: { act: "IV", title: "La prière qui ne prend pas", place: null,
    text: [
      "Aubin prie toute la soirée, les mains à plat sur la jambe noire du garçon. Il prie en latin, puis dans la langue de chez lui, puis sans mots. La sueur lui coule sur le visage malgré le froid. Les veines, sous la peau de Joachim, ne reculent pas. Elles ne montent plus, peut-être. Elles ne reculent pas.",
      "Quand il se relève, enfin, il a les genoux raides et les yeux secs. « Ce n'est pas moi qui manque, dit-il à voix basse, pour toi seul{e}. C'est ce qui est en lui. Il y en a trop. C'est la montagne entière qui est dans sa jambe. » Il se rassied, plus loin, et ne dit plus rien.",
    ],
    choices: [
      { label: "Laver la plaie avec ta fiole d'eau claire", hide: { not: { item: "eau_claire" } }, fx: { drop: "eau_claire", set: { refuge: "gueri" }, flag: ["refuge:sort", "IVD:refuge_eau"], quest: "IVD_refuge", ep: ["seance", 3000], conf: { pip: 8, aubin: 5 }, regard: { IVD_firmin: "redevable" } }, to: "IVD_refuge_gueri" },
      { label: "Poser ta main tachée sur la plaie, et prendre la souillure en toi", tag: "Marque +1", stain: true, fx: { mark: 1, set: { refuge: "marque" }, flag: "refuge:sort", quest: "IVD_refuge", ep: ["seance", 2500], conf: { coliane: -8, aubin: -5 }, fear: { coliane: 5 }, regard: { IVD_firmin: "craintif" } }, to: "IVD_refuge_marque" },
      { label: "Lui demander ce qu'il veut, lui", to: "IVD_refuge_joachim" },
    ] },
  IVD_refuge_gueri: { act: "IV", title: "La fièvre tombe", place: null,
    text: [
      { if: { has: "IVD:refuge_eau" }, text: "Tu défais les bandages. Dessous, la plaie est ouverte et noire, et elle sent la vase de bief. Tu verses l'eau claire dedans, goutte à goutte, comme on te l'a appris ou comme tu crois qu'on le fait. L'eau siffle en touchant la plaie. Le garçon crie, une fois, puis se tait, les yeux grands ouverts. Sous la peau de son cou, les veines noires pâlissent, deviennent grises, deviennent bleues, deviennent des veines." },
      { if: { has: "IVD:refuge_aubin" }, text: "Aubin prie jusqu'à minuit, les mains sur la jambe du garçon, sans s'arrêter, d'une voix de plus en plus basse. Vers minuit, il se tait, mais ses mains restent. Et sous ses mains, quelque chose cède : une odeur de vase monte de la plaie, puis s'en va par le trou du toit avec la fumée. Joachim soupire comme un dormeur, et se met à dormir pour de bon." },
      "Firmin Fermaud se tait longtemps. Il regarde son fils dormir. Puis il se lève, va jusqu'au fond du refuge, fouille dans un coffre, et revient avec une paire de crampons à douze pointes, forgés à la main, la courroie usée par des années de pieds. « Les miens, dit-il. Je n'en aurai plus besoin cet hiver. Je descends le petit chez sa mère. »",
      "Il s'assied près de toi, au feu. « Et je vais vous dire une chose que je n'ai jamais dite à personne d'en bas. Il y a un passage pour monter à l'antre du Vieux, par la face nord, une vire dans la roche, qu'on ne voit que du glacier. Mon père me l'a montrée. Il disait : le Vieux sait qu'on la connaît. Il nous la laisse. C'est sa porte de derrière, pour les amis. »",
    ],
    choices: [{ label: "Prendre les crampons, et la confidence", fx: { item: "IVD_crampons", flag: "IVD:vire" }, to: "IVD_refuge_nuit" }] },
  IVD_refuge_marque: { act: "IV", title: "Ce que tu prends", place: null,
    text: [
      "Tu poses ta main gauche, celle qui porte la tache, à plat sur la plaie. Tu ne sais pas comment tu sais le faire. Ta main le sait. La tache se met à chauffer, puis à boire : tu sens la souillure du garçon remonter dans ta paume, épaisse, tiède, comme de la boue qu'on aspire. Elle remonte ton bras. Elle s'installe. Elle est contente.",
      "Joachim ouvre les yeux. Le blanc de ses yeux est blanc. Il regarde ta main, qui est plus noire qu'avant, jusqu'au milieu de l'avant-bras maintenant, et il ne dit pas merci. Il a peur de toi.",
      "Firmin Fermaud se lève. Il ne s'approche pas. Il te regarde de l'autre côté du feu, et il fait, du bout des doigts, un signe que tu ne connais pas, un signe de chasseur, de vieux montagnard, contre ce qu'on rencontre dans la montagne et qu'on ne nomme pas. Puis il va chercher ses crampons au fond du refuge et te les pose devant toi, sur la pierre, sans te les tendre. « Prenez. On est quittes. »",
      { with: "coliane", text: "Coliane est sortie. Tu l'entends, dehors, frapper la neige à coups de pied, longtemps." },
      { with: "pip", text: "Pip ne revient pas sur ton épaule. Il reste près du garçon, toute la soirée, et le garçon le regarde briller." },
    ],
    choices: [{ label: "Prendre les crampons", fx: { item: "IVD_crampons" }, to: "IVD_refuge_nuit" }] },
  IVD_refuge_joachim: { act: "IV", title: "Ce que veut Joachim", place: null,
    text: [
      "Tu t'assieds au bord du bat-flanc. Le garçon te regarde. Il a les yeux de quelqu'un qui a beaucoup réfléchi, ces quatre jours, couché là, et qui n'a pas pu en parler à son père.",
      "« Je sais ce que c'est, dit-il, tout bas. On en a vu, des bêtes grises, cet été. Quand ça arrive aux yeux, après, on n'est plus soi. On mord. » Il tourne la tête vers le vieux, qui fait semblant de ne pas écouter. « Mon père, il ne pourra pas. Il le sait. Il attend que je le lui demande, et je ne veux pas le lui demander, parce qu'après il faudra qu'il vive avec. » Il te regarde. « Vous, vous allez repartir. »",
      { with: "aubin", text: "Frère Aubin a fermé les yeux. Il se tait. Il n'a rien à dire qui ne soit pas un mensonge." },
    ],
    choices: [
      { label: "Faire ce qu'il demande, cette nuit, pendant que son père dort", fx: { set: { refuge: "abrege" }, flag: "refuge:sort", quest: "IVD_refuge", ep: ["seance", 2000], conf: { pip: -10, coliane: 5 }, regard: { IVD_firmin: "distant" } }, to: "IVD_refuge_abrege" },
      { label: "« Ton père te descendra. Il y a une herboriste, à Vaux. Tiens jusque-là. »", fx: { set: { refuge: "descendu" }, flag: "refuge:sort", quest: "IVD_refuge", ep: ["seance", 1500], conf: { pip: 5 }, regard: { IVD_firmin: "cordial" } }, to: "IVD_refuge_descendu" },
      { label: "Revenir à ce que tu pourrais faire pour sa jambe", back: "IVD_L_refuge" },
    ] },
  IVD_refuge_abrege: { act: "IV", title: "Avant l'aube", place: null,
    text: [
      "Tu attends que les chasseurs dorment. Firmin ne dort pas : il est couché sur le dos, les yeux ouverts dans le noir, et il ne bouge pas quand tu te lèves. Il ne bouge pas quand tu t'agenouilles près de son fils. Il ne bouge pas non plus après.",
      "Le garçon t'a pris la main, au dernier moment, et l'a serrée, et il a dit merci, et c'était la chose la plus difficile à entendre de toute ta vie.",
      "Au matin, Firmin Fermaud creuse dans la neige, devant le refuge, avec un pic à glace, pendant deux heures. Personne ne l'aide. Il ne veut pas. Quand il a fini, il revient vers toi et te tend ses crampons. « Pour la montagne, dit-il. Pas pour vous. » Il ne te regarde pas.",
    ],
    choices: [{ label: "Prendre les crampons, et partir", fx: { item: "IVD_crampons" }, to: "IVD_refuge_matin" }] },
  IVD_refuge_descendu: { act: "IV", title: "Tenir jusque-là", place: null,
    text: [
      "Joachim te regarde longtemps. Puis il hoche la tête, une fois. « D'accord, dit-il. Je tiendrai. Je suis têtu. Mon père dit que je tiens ça de ma mère. » Il a un sourire de travers. Il n'y croit pas tout à fait. Il a décidé d'y croire.",
      { if: { has: "lune:remede" }, text: "Tu dis au vieux le nom de Lune, l'herboriste de Brumefeuille, qui soigne la fièvre grise sous une tente de Vaux et qui en a déjà guéri. Tu le lui dis deux fois, pour qu'il le retienne. Il le répète à voix basse, comme un nom de saint." },
      "Firmin Fermaud fabrique un traîneau, toute la soirée, avec deux skis de frêne et des peaux, en silence. Il part à l'aube, le garçon attaché dessus sous trois couvertures, et deux chiens gris devant. Il te laisse ses crampons, posés sur le seuil, sans un mot.",
    ],
    choices: [{ label: "Prendre les crampons", fx: { item: "IVD_crampons" }, to: "IVD_refuge_nuit" }] },
  IVD_refuge_nuit: { act: "IV", title: "La nuit au refuge", place: null, takes: "night",
    taverne: { mise: 3, adversaire: "un chasseur de chamois de la haute Fenne" },
    fx: { rest: true },
    text: [
      "La nuit, au refuge, les chasseurs parlent du Vieux. Ils en parlent comme d'un voisin difficile qu'on connaît depuis toujours, avec qui on s'est disputé et réconcilié cent fois. Celui-ci l'a vu pêcher des truites dans le lac de la Combe-Noire avec sa queue. Celui-là l'a vu, une nuit de grand froid, couché sur le glacier, les ailes ouvertes, regarder les étoiles pendant des heures.",
      "« Il chantait, dit un autre, le plus jeune, un roux aux sourcils brûlés par la neige. Mon oncle l'a entendu. Pas une chanson de chez nous. Une chanson à six voix, avec la sienne en bas. Il chantait les cinq autres voix tout seul, dans sa tête, et la sienne pour de vrai. Mon oncle disait que ça faisait pleurer. » Les autres rient. Le jeune ne rit pas.",
      "« Depuis la Saint-Martin, dit Firmin, il ne chante plus. Il crie. La nuit. On l'entend jusqu'ici. »",
      { with: "charline", text: "Charline a pris des notes, sur son genou, toute la soirée. Quand les chasseurs se taisent, elle relit à voix basse : « Une chanson à six voix. » Puis elle ferme son carnet et ne dit plus rien." },
    ],
    choices: [{ label: "Dormir jusqu'à l'aube", to: "IVD_refuge_matin" }] },
  IVD_refuge_matin: { act: "IV", title: "Le matin au refuge", place: null,
    text: [
      "L'aube est d'un bleu dur, sans un nuage. Le glacier, au-dessus du refuge, a pris une couleur de lait. Les chasseurs se dispersent dans la montagne sans se dire au revoir, chacun de son côté, comme des chamois.",
      { if: { is: { refuge: "gueri" } }, text: "Firmin et Joachim partent vers le bas, le garçon boitant mais debout, appuyé sur le bâton de son père. Le garçon se retourne trois fois pour te faire signe. À la troisième, son père se retourne aussi." },
      { if: { is: { refuge: "marque" } }, text: "Firmin et son fils sont partis avant que tu te réveilles. Le garçon marchait. Ils n'ont rien laissé derrière eux, pas même la trace de leur feu, comme s'ils voulaient qu'on oublie qu'ils étaient passés." },
      { if: { is: { refuge: "abrege" } }, text: "Devant le refuge, il y a un tas de pierres dans la neige, et en haut du tas, plantée, une corne de chamois. Firmin est parti vers le haut, seul, sans chien. On ne te dit pas où." },
      { if: { is: { refuge: "descendu" } }, text: "Les traces du traîneau descendent la pente en deux lignes parallèles, nettes, jusqu'aux mélèzes. Tu les suis des yeux jusqu'à ce qu'elles tournent." },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  // step 4: the crevasses
  IVD_L_crevasse: { act: "IV", title: "Le champ de crevasses", place: null,
    text: [
      "Vous êtes sur le glacier, maintenant. Pas encore le grand glacier, celui de l'antre : sa langue inférieure, une plaine de glace grise et bossue, couverte d'une neige fraîche qui cache tout. Sous la neige, la glace craque, de temps en temps, avec des claquements secs qui roulent très loin. Et sous la neige, partout, il y a les crevasses.",
      "Tu les devines à peine : un léger creux dans la neige, une ligne plus bleue, un affaissement. Certaines ont trois pas de large. D'autres, un pied, et descendent dans le noir sans qu'on en voie le fond. La neige jette des ponts par-dessus, des ponts qui tiennent ou qui ne tiennent pas, et on ne sait lesquels qu'en marchant dessus.",
      { if: { item: "IVD_carte" }, text: "La carte de ta maîtresse indique un passage, en pointillés, le long d'une bande de pierres qui traverse le glacier comme une couture. *Le pont de glace ne tient que le matin.*" },
    ],
    choices: [
      { label: "Passer en cordée, en sondant chaque pas", if: { item: "corde" }, why: "Il te faudrait une corde.", test: { dom: "nature", diff: 0, label: "Traverser en cordée", help: [H_CRAMPONS, H_CARTE, H_THA] },
        win: { fx: { ep: ["perso", 1500] }, to: "IVD_crev_passe" }, lose: { to: "IVD_crev_chute" } },
      { label: "Lire le glacier, chercher la glace vieille sous la neige neuve", test: { dom: "savoir", diff: -10, label: "Lire la glace", help: [H_CARTE, H_CHA] },
        win: { fx: { ep: ["perso", 1500] }, to: "IVD_crev_passe" }, lose: { to: "IVD_crev_chute" } },
      { label: "« Laisse-moi passer devant, dit Pip. Je vois le creux sous la neige. »", who: "pip", test: { dom: "magie", diff: 0, label: "La lumière de Pip sous la neige" },
        win: { fx: { conf: { pip: 8 }, ep: ["perso", 1500] }, to: "IVD_crev_pip" }, lose: { to: "IVD_crev_chute" } },
      { label: "« Je passe la première, dit Coliane. Je pèse moins que vous. »", who: "coliane", test: { dom: "discretion", diff: 0, label: "Coliane ouvre la trace" },
        win: { fx: { conf: { coliane: 8 }, ep: ["perso", 1500] }, to: "IVD_crev_passe" }, lose: { to: "IVD_crev_chute" } },
      { label: "Contourner tout le champ par la moraine, même si cela prend la journée", fx: { time: 6, food: -1 }, to: "IVD_crev_moraine" },
    ] },
  IVD_crev_pip: { act: "IV", title: "La lumière sous la neige", place: null,
    text: [
      "Pip descend jusqu'à frôler la neige, et sa lumière s'y enfonce. C'est une chose étrange à voir : la neige s'allume par en dessous, d'un bleu laiteux, et là où il y a du vide, la lumière tombe dans le noir et disparaît. Le glacier, sous vos pieds, devient une carte : de grandes taches noires, les crevasses, et entre elles des chemins de bleu, les ponts qui tiennent.",
      "Vous suivez Pip pas à pas. Tous se taisent. À mi-chemin, il s'arrête au-dessus d'une tache noire plus grande que les autres, et ne repart pas. « Il y a quelqu'un, en bas, dit-il. Quelqu'un qui ne bouge plus depuis très longtemps. »",
    ],
    choices: [
      { label: "Descendre voir, à la corde", if: { item: "corde" }, why: "Il te faudrait une corde.", to: "IVD_crev_fond" },
      { label: "Laisser dormir celui qui dort, et passer", back: ROUTE },
    ] },
  IVD_crev_passe: { act: "IV", title: "De l'autre côté", place: null,
    text: [
      "Vous passez. Pas à pas, en sondant, en vous arrêtant chaque fois que la neige fait un bruit qui ne vous plaît pas. Deux fois, un pont s'effondre juste derrière le dernier d'entre vous, et la neige tombe dans le vide en silence. Mais vous passez.",
      "Au bord de la dernière crevasse, la plus large, tu t'arrêtes pour reprendre ton souffle, et tu regardes en bas. La glace est bleue, de plus en plus bleue à mesure qu'elle descend, puis noire. Et dans le bleu, à vingt pas sous toi, prise dans la paroi comme une mouche dans l'ambre, il y a une forme. Un homme. Un bras levé, la main ouverte.",
    ],
    choices: [
      { label: "Descendre voir, à la corde", if: { item: "corde" }, why: "Il te faudrait une corde.", to: "IVD_crev_fond" },
      { label: "Le laisser à la glace, et reprendre la route", back: ROUTE },
    ] },
  IVD_crev_moraine: { act: "IV", title: "La moraine", place: null,
    text: [
      "Vous prenez par la moraine, ce long talus de blocs et de graviers que le glacier a poussé devant lui pendant des siècles. C'est plus sûr. C'est interminable. Les pierres roulent sous les pieds, les chevilles se tordent, et le soleil, réfléchi par la glace, brûle les visages par en dessous.",
      "Vous arrivez de l'autre côté du champ de crevasses au soir, épuisés, les lèvres crevassées. Mais vous arrivez tous.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  IVD_crev_chute: { act: "IV", title: "La chute", place: null,
    fx: { pv: -8 },
    text: [
      "Le pont cède sous toi sans prévenir. Un instant tu marches, l'instant d'après il n'y a plus rien sous tes bottes, et tu tombes dans le bleu, en raclant la paroi, en essayant de t'accrocher à de la glace qui n'offre aucune prise.",
      "Tu t'arrêtes sur une corniche, une marche de glace dans la paroi, à vingt pas sous la surface. Le choc te coupe le souffle. Tu restes allongé{e}, à regarder le petit ruban de ciel, tout en haut, entre les deux lèvres de la crevasse. Il fait très froid et très calme. De l'eau goutte quelque part.",
      "Puis tu tournes la tête, et tu vois qu'il y a quelqu'un d'autre sur la corniche avec toi.",
    ],
    choices: [{ label: "Te redresser", to: "IVD_crev_fond" }] },
  IVD_crev_fond: { act: "IV", title: "Le chevalier dans la glace", place: null,
    fx: { item: ["IVD_lettre_chevalier", "IVD_lame_givre"], ep: ["seance", 2500] },
    text: [
      "Il est pris dans la glace de la paroi jusqu'à la poitrine, debout, comme s'il avait voulu traverser le mur. Un chevalier. La cotte de mailles est intacte sous une couche de givre, le tabard a perdu ses couleurs mais garde sa forme, et à la ceinture, glissé sous le baudrier, il y a un gant gris. Le visage est tourné vers le haut. La glace l'a gardé tel qu'il était au moment de mourir : un homme de quarante ans, la barbe courte, la bouche ouverte. Il ne crie pas. Il a l'air de parler à quelqu'un, là-haut.",
      "Son bras droit est sorti de la glace, levé, la main ouverte. Son épée est restée accrochée à son poignet par la dragonne. Une lame longue, étroite, d'un acier très pâle, qui ne porte pas un grain de rouille. Sur la garde, en lettres anciennes : *VALBRUNE.*",
      "Dans une sacoche de cuir, sous le tabard, durcie par le froid, une lettre. Le sceau est celui de l'Ordre : la main ouverte, dans une cire grise. Il l'avait gardée sur lui. Il avait dû la relire souvent.",
      { if: { has: "passe:ordre" }, text: "Tu connais ce gant. Tu as porté le même, trois ans. Le cuir n'a pas changé de coupe en deux cents ans : on l'a toujours taillé pour une main qui ne se ferme pas tout à fait." },
    ],
    choices: [
      { label: "Lire la lettre", to: "IVD_crev_lettre" },
      { label: "Remonter", to: "IVD_crev_remontee" },
    ] },
  IVD_crev_lettre: { act: "IV", title: "La lettre de Valbrune", place: null,
    text: [
      "Le parchemin se fend aux plis quand tu l'ouvres. L'encre a pâli, mais l'écriture est belle, une écriture de chancellerie, et la date est de l'an 207 du Sceau.",
      "*« À Sire Anseric de Valbrune, chevalier de la Main. Par ordre du Grand Maître. La bête blanche de la Fenne parle, et ce qu'elle dit ne doit pas descendre dans les vallées. Elle a reçu un pèlerin le mois dernier, et ce pèlerin, à son retour, a prêché à Ferrance des choses qu'on a dû faire taire. Vous monterez. Vous ne l'écouterez pas. Vous ne lui répondrez pas, quoi qu'elle vous dise de nos pères. Vous savez ce qu'il faut faire, et vous savez pourquoi on ne l'écrit pas. Que la Main vous garde. »*",
      "Au dos, d'une autre main, au crayon de plomb, tremblée, presque effacée : *Il m'a parlé. Je l'ai écouté. Je redescends le dire.*",
      "Il n'est pas redescendu.",
    ],
    choices: [{ label: "Replier la lettre, et remonter", to: "IVD_crev_remontee" }] },
  IVD_crev_remontee: { act: "IV", title: "Remonter", place: null,
    text: [
      { with: "any", text: "Une corde descend vers toi, puis une voix. On t'a vu{e}. On t'appelle. Tu attaches la corde sous tes bras, et on te hisse, en raclant la paroi, jusqu'au ruban de ciel qui s'élargit." },
      { with: "thavary", text: "C'est Thavary qui tient la corde, les talons plantés dans la neige, le dos rond, en silence. Quand tu sors, elle regarde l'épée pâle à ta ceinture, puis toi, et dit seulement : « Valbrune. C'était une maison de l'Ordre, quand Thavar en était une. Ils ont fini comme nous. »" },
      { without: "any", text: "Personne ne t'attend en haut. Tu remontes seul{e}, en taillant des marches dans la glace avec la lame pâle du chevalier, une marche après l'autre, en soufflant sur tes doigts entre chaque coup. Ça prend une heure. Quand tu sors de la crevasse, tu restes un long moment couché{e} sur la neige, au soleil, les bras en croix." },
      "Le chevalier reste en bas, la main levée. Tu n'as pas pu le sortir de la glace. Tu as pris sa lettre et son épée. Tu ne sais pas encore si c'est un vol ou une promesse.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  // step 5: the pilgrims (side quest IVD_pelerins)
  IVD_L_pelerins: { act: "IV", title: "Les pèlerins", place: null,
    fx: { questSeen: "IVD_pelerins" },
    text: [
      "Tu les vois de loin, d'abord, sans comprendre ce que tu vois : une ligne de bosses régulières sur la neige, au pied de la dernière pente, celle qui monte vers l'antre. Comme des bornes. Puis tu approches, et ce sont des gens.",
      "Trente pèlerins, peut-être plus, à genoux dans la neige, en rang, tournés vers l'antre, les mains jointes ou ouvertes. La neige les a recouverts jusqu'aux épaules. La glace les a pris par-dessous. Leurs visages sont gris, leurs bouches ouvertes sur un chant qui s'est arrêté, et sur leurs joues, leurs mains, leurs cous, la souillure a dessiné des veines noires, comme de l'encre qui aurait coulé de l'intérieur.",
      "Devant eux, au premier rang, il y a une place vide, une forme creusée dans la neige, à genoux. Celui qui était là s'est levé et est parti. Ses traces montent vers l'antre.",
      "Quand tu passes devant le premier rang, l'une des têtes tourne vers toi. Lentement, dans un craquement de glace. Puis une autre.",
      { with: "aubin", text: "Frère Aubin s'est arrêté net. Il a vu des noyés chanter, à Saint-Ivo. Il connaît ce mouvement-là. Ses lèvres ont déjà commencé l'office des morts." },
    ],
    choices: [
      { label: "« Laisse-moi leur parler », dit Frère Aubin, et il s'avance seul", who: "aubin", test: { dom: "magie", diff: -10, label: "L'office des morts sur la glace", help: [H_PIP] },
        win: { fx: { conf: { aubin: 10 }, ep: ["seance", 3000] }, to: "IVD_pel_priere" }, lose: { to: "IVD_pel_combat" } },
      { label: "Passer entre eux, sans bruit, sans les regarder", test: { dom: "discretion", diff: -10, label: "Traverser les rangs", help: [H_PIP, H_COL, H_GLO] },
        win: { fx: { ep: ["seance", 2500] }, to: "IVD_pel_apres" }, lose: { to: "IVD_pel_combat" } },
      { label: "Leur parler, à eux : leurs noms sont gravés à l'oratoire", if: { seen: "IVD_L_oratoire_noms" }, why: "Il faudrait savoir qui ils étaient.", test: { dom: "social", diff: -10, label: "Appeler les pèlerins par leurs noms", help: [H_AUB] },
        win: { fx: { ep: ["seance", 3000], conf: { pip: 5 } }, to: "IVD_pel_priere" }, lose: { to: "IVD_pel_combat" } },
      { label: "Dégainer avant qu'ils se lèvent", to: "IVD_pel_combat" },
    ] },
  IVD_pel_combat: { act: "IV", title: "Ceux qui se lèvent", place: null,
    combat: { title: "Les pèlerins souillés", enemies: [{ id: "IVD_pelerin", n: 3 }], terrain: "nature", spare: true,
      win: { fx: { ep: ["seance", 3000] }, to: "IVD_pel_apres" }, lose: { fx: { pv: -6 }, to: "IVD_pel_apres" },
      calm: { fx: { ep: ["seance", 3000], conf: { pip: 5 } }, to: "IVD_pel_priere" },
      flee: { label: "Reculer jusqu'aux rochers", dom: "nature", diff: -10, to: "IVD_pel_apres" } },
    text: [
      "Ils se lèvent. Trois d'abord, en arrachant leurs genoux à la glace avec un bruit de toile déchirée, puis d'autres derrière, plus lents. Ils ne crient pas. Ils chantent. Le même verset, faux, d'une voix pleine d'eau, et leurs mains jointes s'ouvrent, et les doigts sont noirs jusqu'à la paume.",
    ] },
  IVD_pel_priere: { act: "IV", title: "Le repos", place: null,
    fx: { flag: "IVD:pelerins_apaises" },
    text: [
      { with: "aubin", text: "Aubin s'avance entre les rangs, seul, son bâton planté dans la neige à chaque pas. Il dit l'office des morts, en entier, sans en sauter un mot, d'une voix qui porte loin sur la glace. Il ne regarde pas les têtes qui se tournent vers lui. Il regarde le ciel." },
      { if: { seen: "IVD_L_oratoire_noms" }, text: "Tu dis leurs noms. Ceux de l'oratoire, ceux que tu as lus du bout du doigt. Jeanne. Pierre. Les deux de Merle. Tibaut, neuf ans. Chaque fois qu'un nom tombe sur la neige, une tête se baisse." },
      "Les têtes se baissent l'une après l'autre. Le chant s'arrête. Les mains noires se rejoignent, et le craquement de la glace se tait. Quand le silence revient, ce n'est plus le même silence : c'est celui d'un cimetière, pas celui d'une embuscade.",
      { with: "pip", text: "Pip passe le long des rangs, très bas, et sa lumière effleure chaque visage, un par un. Il ne sait pas pourquoi il le fait. Il le fait jusqu'au bout." },
    ],
    choices: [{ label: "Chercher parmi eux celui qui respire encore", to: "IVD_pel_apres" }] },
  IVD_pel_apres: { act: "IV", title: "Celui qui respire", place: null,
    fx: { meet: "IVD_gaspard" },
    text: [
      { outcome: "lose", text: "Tu es à genoux dans la neige, le souffle court, une plaie au bras qui gèle en saignant. Les pèlerins se sont recouchés, d'eux-mêmes, comme s'ils avaient oublié pourquoi ils s'étaient levés." },
      "À l'écart des rangs, dans un creux de rocher où le vent n'entre pas, il y a un homme assis, recroquevillé, les bras autour des genoux. Il n'est pas pris dans la glace. Il tremble. Il tremble, donc il vit. Quand tu t'approches, il lève la tête, et tu vois les veines noires sur ses tempes, et ses yeux, encore clairs, qui grisaillent au bord.",
      "Sur sa main droite, entre le pouce et l'index, il y a une tache de vin.",
      "« Il est monté, dit-il. Nicaise. Le prêcheur. Il est monté là-haut tout seul, il y a trois jours, en chantant. Il disait que le Vieux l'attendait. Que la dame de l'eau le lui avait dit. » Il rit, un rire qui s'étrangle. « La dame de l'eau. Elle nous parlait dans la glace, la nuit, quand on priait. Elle disait : restez à genoux, et la montagne vous entendra. On est restés à genoux. » Il regarde les rangs. « Je n'ai pas pu. J'avais froid. Je suis parti me cacher là. Je suis le seul qui a eu peur. »",
    ],
    choices: [
      { label: "Lui dire que sa sœur l'attend à Vaux", hide: { not: { seen: "IVD_soeur" } }, to: "IVD_pel_gaspard" },
      { label: "Lui demander son nom", hide: { seen: "IVD_soeur" }, to: "IVD_pel_gaspard" },
    ] },
  IVD_pel_gaspard: { act: "IV", title: "Gaspard", place: null,
    text: [
      { if: { seen: "IVD_soeur" }, text: "« Bastienne », dit-il. Il le dit comme on boit. Puis il pleure, sans bruit, et les larmes gèlent sur ses joues avant de tomber. « Elle m'avait dit de ne pas y aller. Elle m'avait dit que les prêcheurs de Ferrance, ça monte en chantant et ça ne redescend pas. »", else: "« Gaspard, dit-il. De Sorbe-le-Haut. J'ai une sœur, en bas. Elle m'avait dit de ne pas y aller. » Il pleure, sans bruit, et les larmes gèlent sur ses joues avant de tomber." },
      "Il regarde ses mains, les veines noires qui montent du poignet. « Je sens qu'elle me tire, dit-il. La dame. Vers le haut, vers l'antre. J'ai envie d'y aller. J'ai tellement envie d'y aller. Ce n'est pas moi qui ai envie. Mais c'est moi qui marcherai. »",
      { if: { mark: { min: 2 } }, text: "Il te regarde la main gauche, la tache noire qui dépasse de ta manche. Il recule contre le rocher. « Vous aussi, dit-il. Elle vous tient aussi. » Ce n'est pas une question." },
    ],
    choices: [
      { label: "Lui donner ta fiole d'eau claire", hide: { not: { item: "eau_claire" } }, fx: { drop: "eau_claire", set: { pelerins: "sauve" }, flag: ["pelerins:sort", "IVD:pel_eau"], quest: "IVD_pelerins", ep: ["seance", 3000], conf: { pip: 8, aubin: 5, coliane: 5 } }, to: "IVD_pel_sauve" },
      { label: "Frère Aubin pose les mains sur ses tempes", who: "aubin", if: { loyal: "aubin" }, why: "Aubin ne se fie pas assez à toi pour s'y risquer ici, si près de l'antre.", fx: { set: { pelerins: "sauve" }, flag: ["pelerins:sort", "IVD:pel_aubin"], quest: "IVD_pelerins", ep: ["seance", 3000], conf: { aubin: 8 } }, to: "IVD_pel_sauve" },
      { label: "Prendre sa souillure dans ta main tachée", tag: "Marque +1", stain: true, fx: { mark: 1, set: { pelerins: "sauve" }, flag: ["pelerins:sort", "IVD:pel_marque"], quest: "IVD_pelerins", ep: ["seance", 2500], conf: { coliane: -5 } }, to: "IVD_pel_sauve" },
      { label: "Rester avec lui, et le tenir jusqu'à la fin", fx: { set: { pelerins: "paix" }, flag: "pelerins:sort", quest: "IVD_pelerins", ep: ["seance", 2500], conf: { aubin: 5, pip: 3 } }, to: "IVD_pel_paix" },
      { label: "Le laisser monter, puisqu'il le veut", fx: { set: { pelerins: "laisse" }, flag: "pelerins:sort", quest: "IVD_pelerins", ep: ["seance", 1500], conf: { pip: -5 } }, to: "IVD_pel_laisse" },
    ] },
  IVD_pel_sauve: { act: "IV", title: "Redescendre", place: null,
    text: [
      { if: { has: "IVD:pel_eau" }, text: "Tu lui fais boire l'eau claire, à petites gorgées, en lui tenant la tête. Il tousse. Il crache quelque chose de noir sur la neige, une fois, deux fois, et la troisième fois il crache de l'eau ordinaire. Les veines de ses tempes pâlissent. Il regarde ses mains comme on regarde les mains d'un autre." },
      { if: { has: "IVD:pel_aubin" }, text: "Aubin lui prend la tête entre les mains, front contre front, et dit une prière que tu n'as jamais entendue, très courte, qu'il répète. À chaque fois, Gaspard frissonne. À la vingtième, il cesse de frissonner. Aubin se redresse, pâle, les mains tremblantes. « Il y en avait moins que chez le petit du refuge, dit-il. Ou j'en avais plus. »" },
      { if: { has: "IVD:pel_marque" }, text: "Tu poses ta main sur sa nuque. Elle boit. Elle boit sa peur, sa souillure, son envie de monter, et elle te les garde. Gaspard respire, d'un coup, profondément, comme un homme qui sort de l'eau. Ta main, elle, est plus lourde. Tu ne la regardes pas." },
      "Il se lève. Il tient debout. « Je redescends, dit-il. Je redescends le dire. » Tu ne sais pas à qui il compte le dire, ni ce qu'il dira. Il part vers le bas, en suivant vos traces, en se retenant aux rochers, et il ne se retourne pas une seule fois vers l'antre.",
      { if: { has: "refuge:sort" }, text: "Il trouvera le refuge des chasseurs avant la nuit, s'il ne traîne pas. Le feu y sera peut-être encore chaud." },
    ],
    choices: [{ label: "Reprendre la route, vers l'antre", back: ROUTE }] },
  IVD_pel_paix: { act: "IV", title: "La fin de Gaspard", place: null,
    fx: { item: "IVD_medaille" },
    text: [
      "Tu t'assieds à côté de lui, dans le creux du rocher, et tu le prends contre toi, comme on prend un enfant qui a froid. Il te laisse faire. Il parle. Il parle de Sorbe-le-Haut, du moulin de son père, de la foire où ils ont acheté les médailles, de Bastienne qui gagnait toujours à la course jusqu'à douze ans et qui l'a laissé gagner après, pour qu'il ne pleure plus.",
      "La dame de l'eau l'appelle. Tu l'entends aussi, tout bas, dans la glace, sous vous. Il ne lui répond pas. Il te répond à toi. Il parle de plus en plus bas, puis il ne parle plus, et il ne tremble plus, et il a, à la fin, l'air de quelqu'un qui s'est endormi au chaud.",
      "Tu prends sa médaille de la Main, à son cou, sur son lacet. Pour Bastienne. Tu le couches dans le creux du rocher, et tu le couvres de pierres, une à une, assez pour que les corbeaux ne le trouvent pas.",
      { with: "aubin", text: "Aubin dit les mots. Les vrais, ceux qu'on dit pour un homme qui avait un nom et une sœur. Il les dit lentement." },
    ],
    choices: [{ label: "Reprendre la route, vers l'antre", back: ROUTE }] },
  IVD_pel_laisse: { act: "IV", title: "Celui qui monte", place: null,
    text: [
      "Tu t'écartes. Gaspard te regarde, surpris, comme s'il s'attendait à ce qu'on le retienne et qu'il ne sache pas quoi faire maintenant qu'on ne le retient pas. Puis il se lève, et il monte. Lentement. En suivant les traces du prêcheur. Ses lèvres bougent : il chante le verset, le même que les autres, et il chante faux.",
      "Tu le regardes jusqu'à ce qu'il ne soit plus qu'un point noir sur la pente blanche, puis plus rien.",
      { with: "pip", text: "Pip se tait. Il est resté au-dessus du creux du rocher, là où Gaspard s'était caché, et il éclaire la place vide, longtemps, avant de te rejoindre." },
      { with: "coliane", text: "« On ne peut pas sauver ceux qui veulent y aller, dit Coliane. Je l'ai appris à Hautgrès. » Elle n'a pas l'air de croire ce qu'elle dit. Elle a l'air de l'avoir répété souvent." },
    ],
    choices: [{ label: "Reprendre la route, vers l'antre", back: ROUTE }] },
});

// ------------------------------------------------------------------ region fenne: random events (each comes back with @route)
Object.assign(P, {
  EIVD_bouquetins: { act: "IV", title: "Les bouquetins gris", place: null,
    text: [
      "La vire est étroite, une corniche de roche entre la paroi et le vide, et quand tu passes l'angle, ils sont là. Six bouquetins, sur la vire, en travers, qui te barrent le passage. Des mâles, aux cornes annelées longues comme un bras. Ils devraient fuir. Ils ne fuient pas.",
      "Leur pelage est gris, d'un gris de cendre mouillée, et collé par plaques. Leurs yeux sont noirs entièrement. Le plus gros baisse la tête, lentement, et racle la roche du sabot. De sa bouche coule un filet de bave sombre qui gèle en tombant.",
      { with: "gloup", text: "Gloup s'est mis à trembler dans ta besace. Il sent quelque chose que tu ne sens pas. Il sort un œil, puis l'autre, et fait un petit bruit, très doux, comme un appel." },
    ],
    choices: [
      { label: "Les charger avant qu'ils chargent", fight: { title: "La vire aux bouquetins", enemies: [{ id: "IVD_bouquetin", n: 2 }], terrain: "nature",
        win: { fx: { ep: ["perso", 1500] }, to: "EIVD_bouq_fin" }, lose: { fx: { pv: -5 }, to: "EIVD_bouq_fin" },
        flee: { label: "Reculer derrière l'angle de la vire", dom: "nature", diff: -10, to: "EIVD_bouq_attente" } } },
      { label: "Reculer derrière l'angle et attendre qu'ils passent", to: "EIVD_bouq_attente" },
      { label: "Laisser Gloup aller vers eux", who: "gloup", test: { dom: "nature", diff: 0, label: "Gloup parle aux bêtes grises" },
        win: { fx: { conf: { gloup: 10 }, ep: ["perso", 1500] }, to: "EIVD_bouq_gloup" }, lose: { to: "EIVD_bouq_attente" } },
    ] },
  EIVD_bouq_attente: { act: "IV", title: "L'attente", place: null,
    fx: { time: 3 },
    text: [
      "Tu recules derrière l'angle, dos à la paroi, et tu attends. Tu entends les sabots sur la roche, le souffle des bêtes, un raclement. Longtemps. Puis un bruit de pierres qui roulent, et plus rien.",
      "Quand tu passes la tête, la vire est vide. Plus bas, très loin dans le vide, tu vois une tache grise immobile sur un névé. L'un d'eux est tombé. Les autres sont partis vers le haut, vers le glacier, comme tout ce qui est gris dans cette montagne.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  EIVD_bouq_gloup: { act: "IV", title: "Gloup et les bêtes", place: null,
    text: [
      "Gloup roule vers eux sur la vire, tout petit, tout mou, en faisant ce bruit doux. Le gros mâle baisse la tête vers lui. Ils se regardent, la bête de vase et la bête souillée, très longtemps. Puis le bouquetin souffle, une fois, par les naseaux, et s'écarte contre la paroi. Les autres le suivent. Ils vous laissent passer, en vous regardant de leurs yeux noirs, sans bouger.",
      "Quand tout le monde est passé, Gloup revient vers toi. Il ne remonte pas dans ta besace. Il marche à côté de toi, à sa façon, en roulant, et pendant une heure on ne l'entend plus, lui qu'on entend d'ordinaire à dix pas. Puis il se colle contre ta cheville, et tu sens qu'il tremble. Ces bêtes avaient mal sans savoir pourquoi. Il a connu cela, au début.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  EIVD_bouq_fin: { act: "IV", title: "La vire est libre", place: null,
    text: [
      { outcome: "win", text: "Le dernier bouquetin bascule dans le vide sans un cri. Les autres ont fui vers le haut. Sur la vire, il reste du sang noir, qui ne gèle pas, et qui fume." },
      { outcome: "lose", text: "Une corne t'a ouvert la cuisse, et tu as failli passer par-dessus bord. Les bêtes sont parties d'elles-mêmes, vers le haut, quand elles ont eu assez de toi." },
      "Tu passes la vire en t'appuyant à la paroi, sans regarder en bas.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  EIVD_anselme: { act: "IV", title: "Le colporteur", place: null,
    fx: { meet: "anselme" },
    text: [
      "Il y a une mule sur le chemin. Une mule chargée de ballots, qui mâche une touffe d'herbe sèche entre deux rochers, et à côté d'elle, assis sur une pierre, une pipe de terre au bec, un homme à moustache qui te salue de la main comme si vous vous étiez quittés la veille.",
      "« Anselme, dit-il. Mais vous le savez. Tout le monde le sait. » Il a l'air de trouver parfaitement naturel d'être à quatre lieues au-dessus du dernier village, sur un chemin où personne ne passe, avec une mule et des rubans. « Les pèlerins, dit-il. Les pèlerins achètent. Enfin, achetaient. » Il ne s'étend pas sur le sujet.",
      "Il défait un ballot. Des écailles. Une dizaine, grandes comme la main, blanches et nacrées, percées d'un trou pour les pendre au cou. *Écailles du Vieux, porte-bonheur contre le froid et les crevasses.* « Trois sous pièce. Pour vous, deux. » Et à côté, sans y toucher, une fiole de verre épais bouchée de cire, pleine d'une eau qui ne bouge pas quand il secoue le ballot.",
    ],
    choices: [
      { label: "Lui acheter la fiole (30 sous)", if: { gold: { min: 30 } }, why: "Tu n'as pas trente sous.", fx: { gold: -30, item: "eau_claire" }, to: "EIVD_anselme_fin" },
      { label: "Lui demander d'où viennent les écailles", hide: { seen: "EIVD_anselme_ecailles" }, to: "EIVD_anselme_ecailles" },
      { label: "Le saluer et passer", back: ROUTE },
    ] },
  EIVD_anselme_ecailles: { act: "IV", title: "Les écailles", place: null,
    text: [
      "Anselme tire sur sa pipe. « De la nacre de moule de Vel-Orin, dit-il. Polie à la peau de chien. Ça se vend très bien. » Il a l'honnêteté de ceux qui savent qu'on ne les croira pas.",
      "Puis il baisse la voix. « Mais celle-là, non. » Il sort de sa veste une seule écaille, plus grande que les autres, d'un blanc qui n'est pas de la nacre, avec, en son milieu, une tache noire qui a l'air de bouger quand on ne la regarde pas. « Celle-là, je l'ai ramassée au pied du glacier, la semaine dernière. Elle était tombée du ciel. Elle n'est pas à vendre. Je ne sais pas à qui la vendre. Je ne sais même pas si j'ai le droit de la garder. »",
      "Il la remet dans sa veste, vite, comme on cache une chose qui brûle.",
    ],
    choices: [
      { label: "Lui acheter la fiole d'eau (30 sous)", if: { gold: { min: 30 } }, why: "Tu n'as pas trente sous.", fx: { gold: -30, item: "eau_claire" }, to: "EIVD_anselme_fin" },
      { label: "Le saluer et passer", back: ROUTE },
    ] },
  EIVD_anselme_fin: { act: "IV", title: "La fiole", place: null,
    text: [
      "Il compte tes sous sans les regarder, au toucher, et te tend la fiole. L'eau est froide à travers le verre. Elle ne bouge pas, ne frissonne pas, ne fait pas de bulle. « De la grotte bleue, dit-il. Sous le glacier. Je n'y suis pas allé moi-même, je ne suis pas fou. Un chasseur. » Il hausse les épaules. « Pour une fois, ce que je vends est vrai. Ne le dites à personne, ça ruinerait ma réputation. »",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  EIVD_jour_blanc: { act: "IV", title: "Le jour blanc", place: null,
    text: [
      "Le brouillard monte de la vallée en une heure, puis la neige tombe dedans, fine, serrée, et le monde disparaît. Plus de haut, plus de bas. Le ciel et la neige ont la même couleur, la même absence de couleur, et tes yeux ne trouvent rien où s'accrocher. Tu fais un pas et tu ne sais pas si le sol monte ou descend. Tu tends le bras et ta main se perd.",
      "C'est ce que les chasseurs appellent le jour blanc. Ils disent qu'on y tourne en rond jusqu'à s'asseoir, et qu'on s'assied pour ne plus se relever.",
    ],
    choices: [
      { label: "Te guider sur la carte de ta maîtresse et sur la pente", if: { item: "IVD_carte" }, why: "Il te faudrait une carte.", fx: { ep: ["perso", 1000] }, to: "EIVD_blanc_fin" },
      { label: "Chercher la pente au pas, en lançant des boules de neige devant toi", test: { dom: "nature", diff: -10, label: "Marcher dans le jour blanc", help: [H_CRAMPONS, H_COL] },
        win: { fx: { ep: ["perso", 1200] }, to: "EIVD_blanc_fin" }, lose: { to: "EIVD_blanc_perdu" } },
      { label: "« Suivez-moi, dit Pip. Moi, je me vois. »", who: "pip", fx: { conf: { pip: 5 }, ep: ["perso", 1200] }, to: "EIVD_blanc_pip" },
    ] },
  EIVD_blanc_pip: { act: "IV", title: "Une lumière dans le blanc", place: null,
    text: [
      "Dans le blanc, Pip est la seule chose qui ait une forme. Une petite lumière jaune qui flotte devant toi, à hauteur d'yeux, et qui attend que tu la rejoignes avant d'avancer d'un pas. Tu marches vers elle. Elle recule. Tu marches. Pendant des heures, il n'y a rien d'autre au monde qu'elle et toi.",
      "Quand le brouillard se déchire enfin, vous êtes sur le bon chemin, à une portée de fronde de l'endroit où vous l'avez quitté. Pip vient se poser sur ton épaule, épuisé, presque éteint. « C'est drôle, dit-il. J'avais l'impression d'avoir déjà fait ça. Tenir une lumière pour quelqu'un, dans le noir, pendant très longtemps. »",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  EIVD_blanc_perdu: { act: "IV", title: "Perdu dans le blanc", place: null,
    fx: { time: 8, food: -1, pv: -4 },
    text: [
      "Tu marches. Tu marches longtemps. Quand le brouillard se lève enfin, en fin de journée, tu es au pied d'une barre rocheuse que tu n'as jamais vue, à une demi-journée du chemin, les pieds gelés, les cils pris dans le givre, et tu as mangé tes dernières provisions sans t'en rendre compte.",
      "Tu retrouves le chemin à la nuit. Tu as eu de la chance, et tu le sais.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  EIVD_blanc_fin: { act: "IV", title: "Le brouillard se lève", place: null,
    text: [
      "Le brouillard se déchire d'un coup, comme un rideau qu'on tire, et le monde revient : la pente, les rochers, le glacier tout en haut, si près soudain que tu pourrais le toucher. Tu n'as perdu que quelques heures. Ce n'est rien, ici.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  EIVD_ombre: { act: "IV", title: "L'ombre", place: null,
    text: [
      "Une ombre passe sur la neige. Une ombre immense, rapide, qui glisse sur la pente devant toi, puis sur toi, puis derrière, et le froid tombe avec elle, d'un coup, comme quand un nuage cache le soleil en hiver. Tu lèves la tête.",
      "Il passe très haut, au-dessus des crêtes. Long comme une nef d'église, les ailes ouvertes, immobiles, portées par le vent. Blanc. Pas tout à fait blanc : le long des ailes, sur le cou, des traînées sombres, comme de la suie sur un drap. Il ne te regarde pas. Ou s'il te regarde, tu ne le vois pas faire. Il tourne une fois au-dessus du glacier, lentement, comme on tourne autour d'une tombe, et il disparaît derrière la crête.",
      "Un cri descend de la montagne, longtemps après. Pas un rugissement. Un cri. Quelque chose qui a mal.",
      { with: "thavary", text: "Thavary a la main sur la garde de son épée. Elle ne l'a pas tirée. « On ne tue pas ça, dit-elle tout bas. On ne tue pas ça avec une épée. » Puis, plus bas encore : « Ou alors on y passe la vie. »" },
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  EIVD_flaque: { act: "IV", title: "L'eau de fonte", place: null,
    text: [
      "À midi, le soleil fait fondre la neige sur les rochers, et l'eau coule en petits ruisseaux qui se rejoignent dans une cuvette de pierre, au bord du chemin. Une flaque. Claire, comme toute l'eau de neige. Tu te penches pour boire, et ton reflet, au fond, ne se penche pas avec toi.",
      "« {hero}. » La voix est douce, et lasse, comme la voix d'une femme qui a beaucoup veillé. « Tu montes le voir. Le vieux. Je le sais. Je le tiens presque, tu sais. Il ne me manque qu'une main. Il se bat, encore, il est si fort, il est si vieux. Il se bat comme on se bat contre le sommeil. » L'eau frissonne. « Il te dira que je suis méchante. Il dira la vérité. Mais demande-lui ce qu'ils ont fait, les cinq. Demande-lui qui a tenu la chaîne. Et regarde-le bien quand il te répondra. »",
      { if: { has: "voix:nommee" }, text: "Tu sais ce qu'elle est. Tu le sais depuis Hautecombe. Ça ne la rend pas moins douce à entendre. Ça rend seulement la douceur plus difficile à supporter." },
      { if: { mark: { min: 3 } }, text: "Ta main gauche s'est tendue vers la flaque toute seule. Tu la retiens. Elle tire, comme un chien en laisse qui a senti quelque chose." },
    ],
    choices: [
      { label: "Frapper l'eau du pied, et passer", fx: { flag: "IVD:flaque_vue" }, to: "EIVD_flaque_fin" },
      { label: "« Qu'est-ce que tu veux de lui ? »", fx: { flag: "IVD:flaque_vue" }, to: "EIVD_flaque_parle" },
    ] },
  EIVD_flaque_parle: { act: "IV", title: "Ce qu'elle veut", place: null,
    text: [
      "« Ses ailes, dit-elle simplement. Je n'ai jamais volé. Personne n'a jamais rien fait pour moi qui ressemble à des ailes. » L'eau sourit. Tu ne sais pas comment une eau sourit, mais elle le fait. « Et toi, {hero}, tu en as, des ailes ? Tu en voudrais ? Il te suffirait de lui mettre la main sur le front. Je ferais le reste. Il t'obéirait comme un chien. Il te porterait au-dessus de tout le pays. »",
      "La flaque redevient une flaque, et ton reflet se penche enfin vers toi.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  EIVD_flaque_fin: { act: "IV", title: "L'eau brisée", place: null,
    text: [
      "Ta botte fend l'eau en éclats. Le reflet se brise, se recompose, et c'est le tien, cette fois, seul, un peu pâle, les cils pleins de givre. La voix ne revient pas. L'eau, dans la cuvette, recommence à couler vers l'aval, comme si de rien n'était.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },

  EIVD_loups: { act: "IV", title: "Les loups blancs", place: null,
    text: [
      "Ils sortent de la neige comme s'ils en étaient faits. Des loups de la haute Fenne, plus grands que ceux de la plaine, au pelage presque blanc, qui ne laissent presque pas de traces. Quatre. Ils ne sont pas gris. Ils ne sont pas souillés. Ils ont faim, simplement, comme tout ce qui vit encore là-haut, parce que les chamois sont gris et que la viande grise les rend malades.",
      "Ils tournent autour de vous, à distance, sans hâte, en vous regardant manger votre pain.",
    ],
    choices: [
      { label: "Leur jeter tes provisions et passer", if: { food: { min: 1 } }, why: "Tu n'as rien à leur jeter.", fx: { food: -1 }, to: "EIVD_loups_pain" },
      { label: "Leur faire face", fight: { title: "Les loups blancs", enemies: [{ id: "IVD_loup_blanc", n: 3 }], terrain: "nature", spare: true,
        win: { fx: { ep: ["perso", 1500] }, to: "EIVD_loups_fin" }, lose: { fx: { pv: -4 }, to: "EIVD_loups_fin" }, calm: { fx: { ep: ["perso", 1500] }, to: "EIVD_loups_pain" },
        flee: { label: "Reculer en les regardant", dom: "nature", diff: -10, to: "EIVD_loups_fin" } } },
    ] },
  EIVD_loups_pain: { act: "IV", title: "Le pain des loups", place: null,
    text: [
      "Ils mangent. Ils se disputent ce que tu leur as laissé, sans grogner beaucoup, et quand ils ont fini, le plus grand lève la tête et te regarde un long moment. Puis ils s'en vont, vers le haut, en file, sur la neige, sans se retourner.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
  EIVD_loups_fin: { act: "IV", title: "Après les loups", place: null,
    text: [
      { outcome: "win", text: "La neige est rouge, et les loups qui restent s'enfuient. Tu regardes les corps blancs sur la neige blanche. Ils étaient propres. Ils étaient presque les seules choses propres de la montagne." },
      { outcome: "lose", text: "Ils t'ont mordu{e} aux jambes avant de se lasser. Tu bandes les plaies avec ce que tu as, et tu repars en boitant." },
      { outcome: "flee", text: "Tu recules, pas à pas, en les regardant, jusqu'à ce qu'ils se lassent de toi. Ils ne te suivent pas. Ils ont mieux à faire." },
      "Le vent efface les traces en moins d'une heure.",
    ],
    choices: [{ label: "Reprendre la route", back: ROUTE }] },
});

// ------------------------------------------------------------------ the glacier (place glacier)
var DRAGON_DONE = { is: { dragon: ["purifie", "tue", "lie"] } };
Object.assign(P, {
  IVD_glacier: { act: "IV", title: "Le glacier de la Fenne", place: "glacier", hub: true, routes: true, backName: "le pied du grand glacier",
    fx: { ep: ["seance", 2500] },
    text: [
      { first: true, text: "Le grand glacier de la Fenne s'ouvre devant toi d'un coup, au sortir d'un col de pierres noires, et tu t'arrêtes, parce qu'on ne peut pas faire autrement. C'est une vallée entière de glace, une demi-lieue de large, qui monte en pente douce entre deux murailles de roche jusqu'à un cirque fermé, très haut, où les nuages s'accrochent. La glace est bleue sous la neige, d'un bleu de fond de puits, et striée en long de bandes noires, comme si quelqu'un l'avait griffée." },
      { first: true, text: "Au fond du cirque, dans la muraille de droite, il y a une ouverture. Une arche dans la roche, assez haute pour qu'une église y entre sans baisser le clocher. Le glacier monte jusqu'à son seuil, et de l'arche sort, lentement, une haleine de vapeur blanche qui se défait dans l'air froid. L'antre." },
      { first: true, text: "Il n'y a pas un bruit. Pas un oiseau, pas un ruisseau. Seulement, de temps en temps, un craquement très profond, sous tes pieds, qui ne vient pas de la glace. Il vient de dessous la glace. Comme une porte qu'on pousse, et qui tient." },
      { again: true, if: { not: DRAGON_DONE }, text: "Le glacier, l'arche au fond du cirque, l'haleine de vapeur qui en sort. Le craquement sous la glace, de temps en temps, qui fait se taire tout le monde." },
      { if: { is: { dragon: "purifie" } }, text: "Le glacier a changé de couleur. Les bandes noires ont pâli jusqu'au gris, et sur la neige fraîche, le soleil fait des éclats qui piquent les yeux. Au fond du cirque, Ardhal est couché sur le seuil de son antre, la tête sur les pattes, blanc, et il te regarde venir." },
      { if: { is: { dragon: "tue" } }, text: "Le glacier est silencieux. Au fond du cirque, sur le seuil de l'antre, il y a une forme blanche immense, couchée, que la neige commence déjà à recouvrir. Les corbeaux n'osent pas encore descendre." },
      { if: { is: { dragon: "lie" } }, text: "Ardhal est couché au milieu du glacier, et il t'attend. Il t'attend toujours, maintenant. Ses yeux sont noirs, entièrement, et quand tu approches, il baisse la tête jusqu'à la glace." },
      { with: "charline", first: true, text: "Charline a ôté ses moufles et tend les mains vers l'arche, paumes ouvertes, comme pour sentir une chaleur. « Il fait plus chaud là-dedans, dit-elle. Beaucoup plus. Ce n'est pas de la vapeur de glace, c'est son souffle. »" },
      { with: "thavary", first: true, text: "Thavary compte, à mi-voix. Les pas jusqu'à l'arche, la largeur du seuil, les replis de la muraille. Elle s'arrête à mi-compte. « Mon aïeul est monté ici, dit-elle. Thavar le Fidèle. Il est monté ici avec les autres. Il a vu ce que je vois. »" },
      { with: "pip", first: true, text: "Pip s'est posé sur ton épaule et ne la quitte plus. Il tremble un peu. « Ça craque, dit-il. Sous la glace. Ça craque comme quand on serre très fort quelque chose qu'on n'a pas le droit de lâcher. »" },
      { with: "gloup", first: true, text: "Gloup refuse de toucher la glace. Il reste dans ta besace, le nez dehors, et il gémit tout bas chaque fois que le craquement revient." },
    ],
    choices: [
      { label: "La grotte bleue, sous la langue du glacier", hide: { any: [{ has: "IVD:fiole" }, { has: "IVD:main_lavee" }] }, to: "IVD_grotte" },
      { label: "L'ossuaire, au pied de la moraine", hide: { seen: "IVD_ossuaire" }, to: "IVD_ossuaire" },
      { label: "Le cercle de pierres, sur l'éperon", hide: { seen: "IVD_cercle" }, to: "IVD_cercle" },
      { label: "La flaque qui ne gèle pas, au pied de l'arche", hide: { any: [{ seen: "IVD_voix_glace" }, DRAGON_DONE] }, to: "IVD_voix_glace" },
      { label: "Camper au pied de l'éperon, et attendre la nuit", hide: { any: [{ seen: "IVD_bivouac" }, DRAGON_DONE] }, to: "IVD_bivouac" },
      { label: "Monter à l'antre d'Ardhal", big: true, hide: DRAGON_DONE, to: "IVD_antre_seuil" },
      { label: "Descendre vers la porte, sous la glace", big: true, exit: true, hide: { not: DRAGON_DONE }, to: "IVD_porte" },
    ] },

  // the blue cave: clear water, or a hand washed
  IVD_grotte: { act: "IV", title: "La grotte bleue", place: "glacier",
    text: [
      "Sous la langue du glacier, là où la glace vient mourir contre les rochers, il y a une bouche. Une fente basse dans la glace, d'où sort un ruisseau, et au-dessus du ruisseau, un rideau de stalactites de glace, serrées comme les barreaux d'une grille, de la taille d'un homme. Derrière, une lumière bleue, si bleue qu'elle a l'air d'être une couleur qu'on ne connaît pas.",
      "Le ruisseau qui sort de là est clair. Pas seulement clair : il n'a pas de couleur du tout, et il ne fait pas de bruit en coulant sur les pierres. C'est la seule eau de toute la montagne qui ne soit ni grise ni tiède.",
      { if: { item: "IVD_carte" }, text: "*Celle de la grotte bleue, oui.* La phrase de ta maîtresse, soulignée deux fois." },
    ],
    choices: [
      { label: "Briser les stalactites avec la lame pâle de Valbrune", if: { item: "IVD_lame_givre" }, why: "Il te faudrait une lame qui ne casse pas sur la glace.", fx: { ep: ["perso", 1200] }, to: "IVD_grotte_eau" },
      { label: "Te glisser entre les barreaux de glace, à plat ventre dans le ruisseau", test: { dom: "discretion", diff: -10, label: "Ramper sous la grille de glace", help: [H_FOURRURE] },
        win: { fx: { ep: ["perso", 1200] }, to: "IVD_grotte_eau" }, lose: { fx: { pv: -4 }, to: "IVD_grotte_eau" } },
      { label: "Faire fondre la grille, doucement, pour ne pas troubler l'eau", who: "charline", test: { dom: "magie", diff: 0, label: "Un feu sans fumée" },
        win: { fx: { conf: { charline: 5 }, ep: ["perso", 1200] }, to: "IVD_grotte_eau" }, lose: { fx: { pv: -2 }, to: "IVD_grotte_eau" } },
      { label: "Laisser Gloup se glisser dedans et ouvrir le passage", who: "gloup", fx: { conf: { gloup: 5 }, ep: ["perso", 1200] }, to: "IVD_grotte_eau" },
      { back: "IVD_glacier" },
    ] },
  IVD_grotte_eau: { act: "IV", title: "L'eau d'avant", place: "glacier",
    text: [
      { outcome: "lose", text: "Tu t'es écorché les mains et le front sur la glace, et tu es trempé{e} jusqu'aux os. Mais tu es passé{e}." },
      "Derrière la grille, une salle. Ronde, haute, entièrement de glace, une glace si vieille qu'elle n'a plus de bulles, plus de stries, plus rien : un bleu pur, épais, qui fait paraître ta peau morte. Au fond, la glace pleure. Un filet d'eau suinte de la paroi, goutte à goutte, et tombe dans une vasque de pierre qu'aucune main n'a creusée.",
      "Cette glace-là est tombée en neige avant la Brèche. Avant les Six. Avant qu'il y ait un Sceau. L'eau qui en sort ne sait rien de ce qui est arrivé depuis.",
      "Le filet est mince. Tu le regardes remplir la vasque, très lentement. Il y en a assez pour une fiole, peut-être. Pas pour deux. La vasque ne se remplit pas plus vite qu'une larme ne tombe.",
      { with: "gloup", text: "Gloup a sauté dans la vasque avant qu'on puisse le retenir. Il en ressort aussitôt en piaillant, propre, transparent, et pendant un instant on voit à travers lui la glace bleue. Puis il se secoue, et redevient Gloup. Il claque de tout son corps, comme d'autres claquent des dents. L'eau de la vasque n'a pas changé de couleur." },
    ],
    choices: [
      { label: "Remplir une fiole d'eau claire", fx: { item: "eau_claire", flag: "IVD:fiole", ep: ["perso", 1500] }, to: "IVD_grotte_fin" },
      { label: "Plonger ta main tachée dans la vasque", hide: { mark: { max: 0 } }, fx: { mark: -1, flag: "IVD:main_lavee", ep: ["perso", 1500], conf: { coliane: 5, aubin: 5, pip: 5 } }, to: "IVD_grotte_main" },
    ] },
  IVD_grotte_main: { act: "IV", title: "La main dans l'eau", place: "glacier",
    text: [
      "Tu plonges la main. Le froid te mord jusqu'à l'épaule, un froid si complet que pendant un instant tu ne sens plus rien, plus ton bras, plus ton corps, plus le monde. Puis la douleur arrive, propre, simple, une douleur de main gelée et rien d'autre.",
      "Quand tu retires ta main, la tache a reculé. Pas disparu : reculé, d'un pouce, d'un doigt, et ses bords sont gris au lieu d'être noirs. Dans la vasque, l'eau est devenue trouble. Elle ne redeviendra pas claire avant longtemps. Tu as pris pour toi ce qui aurait pu servir à un autre.",
      { with: "coliane", text: "Coliane a vu. Elle ne dit rien, mais elle pose la main sur ton épaule en passant, une seconde, et la retire." },
    ],
    choices: [{ label: "Ressortir de la grotte", back: "IVD_glacier" }] },
  IVD_grotte_fin: { act: "IV", title: "La fiole", place: "glacier",
    text: [
      "Tu remplis la fiole, en la tenant sous le filet, très longtemps, jusqu'à ce que l'eau atteigne le col. Tu la bouches avec de la cire. L'eau, dedans, ne bouge pas. Elle a le poids d'une chose qui compte.",
      "Quand tu ressors, la vasque est vide, et le filet tombe dans le fond sec avec un petit bruit, le seul de la grotte.",
      { with: "pip", text: "Pip regarde la fiole de tout près, son reflet doré dans le verre. « Elle est comme moi, dit-il. Elle ne sait pas d'où elle vient. Elle sait juste qu'elle est propre. »" },
    ],
    choices: [{ label: "Ressortir de la grotte", back: "IVD_glacier" }] },

  // the ossuary: those who came before
  IVD_ossuaire: { act: "IV", title: "L'ossuaire", place: "glacier",
    text: [
      "Au pied de la moraine, là où le glacier rejette ce qu'il a avalé, il y a des os. Beaucoup d'os. Des côtes, des crânes, des fémurs, mêlés aux pierres comme du gravier, polis par la glace, blanchis par des siècles de soleil. Des armes aussi : des lames rongées, des fers de lance, des bosses de boucliers, des cuirasses de toutes les époques, la plus vieille si rouillée qu'elle n'a plus de forme, la plus récente encore brillante.",
      "Ce sont ceux qui sont montés tuer le dragon. Chevaliers, chasseurs de primes, aventuriers, princes cadets qui voulaient une légende. Le glacier les a rendus, avec le temps, comme il rend tout.",
      "Au milieu des os, un crâne de troll, énorme, avec une seule défense cassée, et entre ses dents, plantée là comme une fleur dans un vase, une épée d'apparat dorée. Quelqu'un a eu de l'humour, il y a longtemps.",
      { with: "thavary", text: "Thavary s'est accroupie près d'un bouclier à demi enterré. Elle le dégage. Sur la bosse rouillée, on lit encore un écu : un anneau d'or sur champ de sable. « Thavar, dit-elle. Ils sont montés aussi. Ils ont essayé de le faire taire, eux aussi. » Elle reste longtemps accroupie, le bouclier sur les genoux." },
      { if: { has: "grauk:mort" }, text: "En regardant le crâne du troll, tu penses malgré toi à Grauk, sur son trône, et à la façon dont il est tombé. Les trolls aussi ont eu leurs héros. Personne ne les a jamais chantés." },
    ],
    choices: [
      { label: "Enterrer ce que tu peux, sous des pierres", fx: { time: 4, conf: { aubin: 5, pip: 5, thavary: 3 }, ep: ["perso", 1500] }, to: "IVD_ossuaire_tombe" },
      { label: "Fouiller les os pour ce qui peut servir", fx: { gold: 30, conf: { pip: -3 }, ep: ["perso", 800] }, to: "IVD_ossuaire_fouille" },
      { label: "Les laisser au glacier", back: "IVD_glacier" },
    ] },
  IVD_ossuaire_tombe: { act: "IV", title: "Les cairns", place: "glacier",
    text: [
      "Tu ne peux pas tout enterrer. Il faudrait une saison. Tu fais des tas, des cairns, de pierres plates, sur ce que tu peux rassembler : un cairn pour les chevaliers, un pour les chasseurs, un pour ceux que tu ne reconnais pas. Un pour le troll, à part, parce qu'il ne serait pas content d'être avec les autres.",
      { with: "aubin", text: "Aubin bénit chaque cairn. Il ne connaît pas leurs noms. Il dit : « Ceux qui sont montés, et qui ne sont pas redescendus. » Ça suffit." },
      { with: "thavary", text: "Thavary pose le bouclier de Thavar sur le cairn des chevaliers, l'écu vers le ciel. « Qu'il reste là, dit-elle. Qu'il serve à quelque chose. »" },
      "Quand tu as fini, le soleil a tourné, et les ombres des cairns s'allongent sur la neige, l'une à côté de l'autre, comme des gens qui attendent.",
    ],
    choices: [{ label: "Revenir au pied du glacier", back: "IVD_glacier" }] },
  IVD_ossuaire_fouille: { act: "IV", title: "Ce que les morts portaient", place: "glacier",
    text: [
      "Tu fouilles. Des bourses de cuir pourri, dont les pièces sont tombées entre les côtes : des sous de toutes les frappes, des deniers carrés d'avant le Sceau, deux couronnes d'Aldaran à l'effigie d'un roi dont personne ne se souvient. Une trentaine de sous en tout, une fois triés.",
      "Tu remets un crâne à l'endroit, pour ne pas qu'il te regarde de travers. C'est idiot. Tu le fais quand même.",
      { with: "pip", text: "Pip ne t'a pas suivi{e} dans les os. Il t'attend à l'écart, très pâle. Il ne te demande rien." },
    ],
    choices: [{ label: "Revenir au pied du glacier", back: "IVD_glacier" }] },

  // the circle of stones on the spur
  IVD_cercle: { act: "IV", title: "Le cercle de pierres", place: "glacier",
    fx: { ep: ["perso", 1500] },
    text: [
      "Sur l'éperon qui domine le glacier, face à l'antre, quelqu'un a dressé six pierres en cercle. Des dalles de schiste plantées debout, à hauteur de siège, autour d'un foyer de pierres noircies où personne n'a fait de feu depuis des siècles. Le vent passe entre elles avec un son bas, continu, comme une note tenue.",
      "Sur cinq des pierres, un nom a été gravé, profondément, en lettres anciennes que la glace a adoucies : *ALDAR. ORINE. THAVAR. HILDRE. IVO.* Sur la sixième, rien. Pas de nom effacé, pas de trace de gouge. Seulement, au ras du sol, gravée petit, une main ouverte, et dans la paume, un rond.",
      "La sixième pierre est la seule tournée vers l'antre. Les cinq autres regardent le feu.",
      { with: "pip", text: "Pip va s'asseoir sur la sixième pierre. Il ne sait pas pourquoi. Il dit qu'elle est tiède. Elle n'est pas tiède : tu y poses la main, elle est froide comme les autres. Il dit qu'elle est tiède pour lui." },
      { with: "charline", text: "Charline s'est assise sur la pierre d'Hildre. Elle passe le doigt dans les lettres. « Mon arrière-arrière-je-ne-sais-combien-grand-mère, dit-elle. Elle s'est assise là. Elle a fait un feu là. » Elle regarde le foyer mort. Elle n'y met pas le feu." },
      { with: "thavary", text: "Thavary reste debout derrière la pierre de Thavar. Elle ne s'assied pas. Elle n'en a pas le droit, dit-elle, ou elle n'en a pas envie : elle ne précise pas." },
    ],
    choices: [
      { label: "T'asseoir sur la sixième pierre, et regarder l'antre", fx: { conf: { pip: 5 } }, to: "IVD_cercle_assis" },
      { label: "Revenir au pied du glacier", back: "IVD_glacier" },
    ] },
  IVD_cercle_assis: { act: "IV", title: "La place vide", place: "glacier",
    text: [
      "Tu t'assieds. La pierre est froide. De là, on voit tout : le glacier en contrebas, l'arche de l'antre en face, et plus loin, derrière, vers l'ouest, toute la vallée de la Sorbe jusqu'aux collines, sous une brume grise.",
      "Tu restes assis{e} longtemps. Tu penses à quelqu'un qui s'est assis ici, il y a quatre cents ans, le plus jeune, et qui regardait l'antre pendant que les cinq autres regardaient le feu. Tu ne sais pas à quoi il pensait. Tu sais seulement qu'il est descendu, le lendemain, sous la glace, et qu'il n'en est pas remonté.",
    ],
    choices: [{ label: "Revenir au pied du glacier", back: "IVD_glacier" }] },

  // the Voice in the glacier water: the offer of the binding
  IVD_voix_glace: { act: "IV", title: "La flaque sous l'arche", place: "glacier",
    fx: { flag: "IVD:voix_glacier" },
    text: [
      "Au pied de l'arche, à vingt pas du seuil, il y a une flaque que l'haleine du dragon garde liquide. Une eau grise, épaisse, qui fume. Tout autour, la neige est noire sur une toise, comme brûlée par du froid.",
      "Elle est là. Tu le sais avant qu'elle parle. La flaque se plisse, se creuse, et dans le creux un visage se forme, un visage de femme, de vase et de cheveux d'algue, qui te regarde avec une immense tendresse.",
      "« {hero}. Tu es venu{e} jusqu'ici. Tu es venu{e} jusqu'à lui. » Elle regarde vers l'arche. « Il souffre, tu sais. Il a si mal. Ça fait quatre cents ans qu'il garde cette porte pour des gens qui l'ont envoyé ici pour qu'il se taise. Moi, je peux lui ôter le mal. Je peux lui ôter la mémoire, et la honte, et le froid. Il suffit que quelqu'un lui pose la main sur le front, une main qui me porte, et qu'il accepte de ne plus lutter. »",
      "« Ce n'est pas une chaîne, dit-elle doucement. C'est un repos. Et il t'appartiendrait. Pense à ce que tu ferais, avec des ailes. Pense à ce que tu pourrais protéger. »",
      { if: { mark: { max: 0 } }, text: "« Tu n'as pas de tache, ajoute-t-elle, presque surprise. Tu as tout refusé. C'est rare. Je te la donnerais, si tu me la demandais. Il n'est jamais trop tard pour demander. »" },
    ],
    choices: [
      { label: "« Non. »", fx: { conf: { coliane: 3, aubin: 3 } }, to: "IVD_voix_refus" },
      { label: "Ne rien répondre, et t'éloigner", back: "IVD_glacier" },
    ] },
  IVD_voix_refus: { act: "IV", title: "Non", place: "glacier",
    text: [
      "Elle ne se fâche pas. Elle ne se fâche jamais. Elle te regarde avec la même tendresse, un peu triste maintenant, comme une mère regarde un enfant qui refuse de manger. « Tu changeras d'avis, dit-elle. Quand tu l'auras vu. Quand il t'aura parlé. On change toujours d'avis, devant lui. Les cinq ont changé d'avis. »",
      "Le visage se défait. La flaque redevient une flaque, grise, fumante. Un caillou que tu y jettes s'enfonce sans faire de rond.",
    ],
    choices: [{ label: "Revenir au pied du glacier", back: "IVD_glacier" }] },

  // the night on the spur, and the companions around the fire
  IVD_bivouac: { act: "IV", title: "La nuit sur l'éperon", place: "glacier", takes: "night",
    fx: { rest: true, ep: ["perso", 1500] },
    text: [
      "Vous campez à l'abri de l'éperon, sous un surplomb, avec ce que vous avez pu monter de bois. Le feu est petit. La nuit tombe très vite, ici, et elle est d'un froid qui fait mal aux dents. Au-dessus du cirque, les étoiles sont si nombreuses et si nettes qu'on dirait du givre sur une vitre noire.",
      "Vers minuit, l'antre s'allume. Une lueur bleue, pâle, qui pulse lentement au fond de l'arche, comme un cœur. Puis un cri. Long, déchiré, qui rebondit d'une muraille à l'autre et ne finit pas. Puis la lueur s'éteint, et le silence revient, plus lourd.",
      { without: "any", text: "Tu veilles seul{e}, le dos au rocher, les genoux sous le menton. Personne pour te dire ce que tu dois faire demain. Personne non plus pour te dire que tu as tort. Tu ne sais pas lequel des deux te manque le plus." },
      { with: "any", text: "Personne ne dort vraiment. On se parle à voix basse, deux par deux, au bord du feu, de ce qu'il faudra faire demain, et de ce qu'on fera si on ne peut pas le faire." },
    ],
    choices: [
      { label: "Parler avec Pip", with: "pip", once: true, to: "IVD_feu_pip" },
      { label: "Parler avec Coliane", with: "coliane", once: true, to: "IVD_feu_coliane" },
      { label: "Parler avec Charline", with: "charline", once: true, to: "IVD_feu_charline" },
      { label: "Parler avec Frère Aubin", with: "aubin", once: true, to: "IVD_feu_aubin" },
      { label: "Parler avec Thavary", with: "thavary", once: true, to: "IVD_feu_thavary" },
      { label: "Parler avec Gloup", with: "gloup", once: true, to: "IVD_feu_gloup" },
      { label: "Dormir, enfin, jusqu'à l'aube", big: true, back: "IVD_glacier" },
    ] },
  IVD_feu_pip: { act: "IV", title: "Pip, au bord du feu", place: "glacier", with: "pip",
    fx: { conf: { pip: 5 } },
    text: [
      "Pip s'est posé sur une pierre au bord du feu, et il regarde les flammes, qui sont plus jaunes que lui. « Tu vas le tuer ? » demande-t-il. Il le demande comme il demande tout, sans reproche, parce qu'il veut savoir.",
      "Tu ne sais pas. Tu le lui dis. Il réfléchit. « Moi, je voudrais qu'on le lave, dit-il. Comme Gloup. Je voudrais qu'on lui enlève ce qui lui fait mal et qu'il reste lui. Mais je ne sais pas si on peut. » Il se tait. « Et je ne voudrais pas qu'on l'attache. Je ne sais pas pourquoi. Rien que d'y penser, ça me serre. Comme une main qui se ferme. »",
      { if: { item: "eau_claire" }, text: "Il regarde ta besace, là où tu ranges la fiole. « Avec l'eau, dit-il, et moi. Je pourrais essayer. Je ne sais pas comment, mais je pourrais essayer. Je crois que je saurais, une fois là-bas. »" },
    ],
    choices: [{ back: "IVD_bivouac" }] },
  IVD_feu_coliane: { act: "IV", title: "Coliane, au bord du feu", place: "glacier", with: "coliane",
    fx: { conf: { coliane: 5 } },
    text: [
      "Coliane affûte un couteau. Elle le fait toujours quand elle ne veut pas parler, et elle parle quand même, au bout d'un moment, sans lever les yeux. « Tu as entendu le cri ? C'est le cri d'une bête qui a mal. J'en ai achevé, des bêtes qui criaient comme ça. On les achève parce qu'on les aime, pas parce qu'on les hait. »",
      "Elle teste le fil sur son pouce. « Mais lui, il parle. On dit. Alors on lui demande. C'est tout. On lui demande ce qu'il veut. Et s'il veut mourir, on le fait bien. Et s'il veut vivre, on trouve. » Elle te regarde enfin. « Et si quelqu'un te propose de le tenir en laisse, tu lui craches dessus. D'accord ? »",
      { if: { mark: { min: 3 } }, text: "Elle regarde ta main. Longtemps. Elle ne dit rien de plus. Elle n'a pas besoin." },
    ],
    choices: [{ back: "IVD_bivouac" }] },
  IVD_feu_charline: { act: "IV", title: "Charline, au bord du feu", place: "glacier", with: "charline",
    fx: { conf: { charline: 5 } },
    text: [
      "Charline a sorti son carnet. Elle n'écrit rien. Elle le tient ouvert sur ses genoux, comme on tient une main. « Un dragon de givre, dit-elle. Je l'ai lu cent fois, à l'Athénée, dans les bestiaires. Ce qui les tue, c'est le feu. Le vrai. Pas le feu de cheminée. Le feu de forge. » Elle regarde ses mains. « Je pourrais. Je crois. Si on doit en arriver là. »",
      "Puis, plus bas : « Mais Hildre était son amie. C'est écrit, dans un vieux livre que personne ne lit. Hildre a forgé une chaîne pour un homme, et elle a soigné l'aile d'un dragon, la même année. Je ne sais pas laquelle des deux choses je voudrais avoir faite. » Elle referme le carnet. « Je sais laquelle je voudrais ne pas avoir faite. »",
    ],
    choices: [{ back: "IVD_bivouac" }] },
  IVD_feu_aubin: { act: "IV", title: "Aubin, au bord du feu", place: "glacier", with: "aubin",
    fx: { conf: { aubin: 5 } },
    text: [
      "Aubin a les mains tendues vers le feu, et elles tremblent un peu, de froid ou d'autre chose. « Je pourrais essayer de le laver, dit-il sans préambule. Comme le garçon. Comme les autres. Je ne sais pas si j'en ai la force. Il y a tant de souillure dans cette bête qu'on la sent d'ici, comme on sent un charnier. »",
      "« Mais il faudrait que j'y croie, dit-il. Que je croie que ce que je fais sert à quelque chose. Il faudrait que tu y croies aussi. Je ne peux pas laver seul. Je ne l'ai jamais pu. À Saint-Ivo, cette nuit-là, je n'étais pas là, et ils sont morts. Si je suis là, cette fois, et que tu es là, peut-être... » Il s'arrête. « Je dis des bêtises. Il fait froid. »",
      { if: { not: { loyal: "aubin" } }, text: "Il te regarde, et tu vois qu'il ne sait pas s'il peut compter sur toi. Il ne te le reproche pas. Il le constate, comme on constate le temps qu'il fait." },
    ],
    choices: [{ back: "IVD_bivouac" }] },
  IVD_feu_thavary: { act: "IV", title: "Thavary, au bord du feu", place: "glacier", with: "thavary",
    fx: { conf: { thavary: 5 } },
    text: [
      "Thavary est assise en tailleur, l'épée en travers des genoux. « Mon aïeul est monté ici, dit-elle. Et il a dit oui. Il a dit oui à la chaîne. Il a écrit, après, qu'il laissait à ses héritiers la honte qui va avec. » Elle a un petit rire sec. « Je l'ai, la honte. Je l'ai reçue. Je ne sais pas quoi en faire. »",
      "« Si on doit le tuer, je le tuerai, dit-elle. Proprement, de face. C'est une chose que je sais faire. Mais si on doit le lier, si on doit lui mettre une chaîne de plus pour qu'il nous serve, ne me demande pas de tenir le bout. Ça, ma maison l'a déjà fait une fois. »",
      { if: { has: "thavary:aveu" }, text: "Elle t'a dit, à l'Isarde, ce que le conseiller lui offrait pour l'Anneau. Elle n'y revient pas. Elle dit seulement : « Au moins, toi, tu sais ce que je vaux, et ce que j'ai failli valoir. Ça repose. »" },
      { if: { has: "thavary:secret" }, text: "Elle se tait, longtemps. Tu as l'impression qu'elle va dire autre chose, quelque chose qu'elle garde depuis l'Isarde. Puis elle se lève, et va voir si le bois est sec." },
    ],
    choices: [{ back: "IVD_bivouac" }] },
  IVD_feu_gloup: { act: "IV", title: "Gloup, au bord du feu", place: "glacier", with: "gloup",
    fx: { conf: { gloup: 5 } },
    text: [
      "Gloup est loin du feu, parce qu'il n'aime pas le feu, mais assez près pour avoir chaud. Il te regarde de ses deux yeux ronds. Puis il étire un bout de lui-même vers l'antre, longuement, et le ramène contre son ventre.",
      "Tu lui demandes ce qu'il veut dire. Il n'a pas de mots, il n'en a jamais eu. Il crache sur la pierre un peu de vase grise, la regarde, te regarde. Le Vieux en a dedans, lui aussi, et ne sait plus ce qui est lui et ce qui est elle. Gloup se tortille. Lui, on ne l'a pas tué. On ne l'a pas attaché. On lui a demandé, à ta façon, et il a répondu à la sienne. Il rampe un peu plus près, et te pousse le genou du front, deux fois, du côté de l'arche.",
    ],
    choices: [{ back: "IVD_bivouac" }] },

  // the threshold of the lair: several ways in
  IVD_antre_seuil: { act: "IV", title: "Le seuil de l'antre", place: "glacier",
    text: [
      "De près, l'arche est encore plus haute. La roche, autour, est polie comme du marbre par des siècles de passages, et le seuil est une dalle de glace bleue, lisse, creusée au milieu par le poids d'un corps qui s'y couche depuis toujours. L'haleine qui sort de l'antre te passe sur le visage. Elle est tiède, et elle sent la pierre mouillée, le fer, et en dessous, plus faible, la vase.",
      "À l'intérieur, une grande salle s'enfonce dans la montagne, éclairée d'une lumière bleue qui tombe d'on ne sait où. Et au fond de la salle, couché, il y a quelque chose de si grand que tu le prends d'abord pour un repli de la roche.",
      { if: { has: "IVD:vire" }, text: "À droite de l'arche, si on sait où regarder, une vire monte dans la paroi, une étroite corniche de roche que les chasseurs connaissent. La porte de derrière, disait Firmin. Pour les amis." },
    ],
    choices: [
      { label: "Entrer à découvert, et appeler", to: "IVD_antre_parole" },
      { label: "Te glisser le long de la paroi, pour le voir avant qu'il te voie", test: { dom: "discretion", diff: -20, label: "Approcher un dragon qui dort", help: [H_PIP, H_COL, H_FOURRURE] },
        win: { fx: { ep: ["seance", 2500] }, to: "IVD_antre_discret" }, lose: { to: "IVD_antre_eveil" } },
      { label: "Entrer l'arme au poing", to: "IVD_antre_force" },
      { label: "Prendre la vire des chasseurs", hide: { not: { has: "IVD:vire" } }, fx: { ep: ["seance", 2500] }, to: "IVD_antre_vire" },
      { label: "« Laisse-moi entrer le premier », dit Pip", who: "pip", fx: { conf: { pip: 8 }, ep: ["seance", 2500] }, to: "IVD_antre_pip" },
      { label: "Thavary dégaine et s'avance pour se présenter, à la manière ancienne", who: "thavary", fx: { conf: { thavary: 8 }, ep: ["seance", 2500] }, to: "IVD_antre_thavary" },
      { label: "Redescendre au pied du glacier", back: "IVD_glacier" },
    ] },
  IVD_antre_parole: { act: "IV", title: "Appeler", place: "glacier",
    text: [
      "Tu entres au milieu de la salle, les mains vides et visibles, et tu t'arrêtes à trente pas du repli de roche qui n'en est pas un. Ta voix, quand tu appelles, monte sous la voûte et revient vers toi trois fois, de plus en plus faible.",
      "Le repli de roche bouge. Une paupière s'ouvre, grande comme une porte de grange, sur un œil d'un bleu très pâle, presque blanc, où la pupille est une fente noire. L'autre œil, à côté, ne s'ouvre pas : il est déjà ouvert, et il est noir, entièrement, sans blanc et sans pupille, comme un trou dans de la glace.",
      "« Tu as appelé, dit une voix. Ça faisait longtemps. Les autres ne m'appellent plus : ils prient, ou ils crient. »",
    ],
    choices: [{ label: "Faire face à Ardhal", big: true, to: "IVD_ardhal" }] },
  IVD_antre_discret: { act: "IV", title: "Le dragon qui dort", place: "glacier",
    fx: { flag: "IVD:vu_dormir" },
    text: [
      "Tu longes la paroi, pas après pas, sur la glace qui ne craque pas. Le repli de roche, au fond, devient une forme. La forme devient une bête. La bête dort.",
      "Il est immense, et il est vieux. Ses écailles sont blanches, mais d'un blanc d'os, d'ivoire jauni, et entre elles, dans les jointures, une matière noire a poussé, luisante, comme un lichen ou comme une moisissure. Elle forme des veines, le long de son cou, de ses flancs, de ses ailes repliées, et les veines battent, lentement, au rythme de son souffle. Une de ses pattes de devant est entièrement noire, jusqu'à l'épaule. Elle tremble dans son sommeil.",
      "Tu vois aussi ce que tu n'aurais pas vu de face : sous son aile gauche, contre son flanc, il garde quelque chose. Un corps d'homme, en robe de prêcheur, couché en rond comme un chien contre sa mère. Le dragon l'a pris contre lui. Pour le réchauffer, ou pour le garder. L'homme ne bouge plus depuis longtemps.",
      "« Je t'entends respirer, dit le dragon sans ouvrir les yeux. Depuis l'arche. Tu respires comme quelqu'un qui a peur et qui ne veut pas reculer. Approche. Je ne suis pas encore à elle. »",
    ],
    choices: [{ label: "Faire face à Ardhal", big: true, to: "IVD_ardhal" }] },
  IVD_antre_eveil: { act: "IV", title: "Le réveil", place: "glacier",
    fx: { pv: -10 },
    text: [
      "Un caillou roule sous ta botte. Rien. Un bruit de rien. L'œil noir s'ouvre aussitôt, et la tête se lève, et le souffle vient.",
      "Ce n'est pas du feu. C'est du froid. Un froid blanc, qui sort de sa gueule en nuage et qui t'enveloppe, et qui gèle tout : tes cils, ta salive, l'air dans ta gorge. Tu tombes à genoux, la peau brûlée de givre, et tu entends un grondement au-dessus de toi, énorme, rauque, et dans le grondement, deux voix. L'une crie. L'autre dit, très calmement : *Mange.*",
      "Puis le souffle s'arrête. La tête du dragon s'abat sur la glace, à dix pas de toi, et il se met à trembler de tout son corps, longtemps, les yeux fermés, comme un homme qui lutte contre une crise. Quand il les rouvre, l'œil pâle te regarde. L'œil noir aussi.",
      "« Pardon, dit-il. Elle est plus rapide que moi, quand on me surprend. Ne me surprends plus. »",
    ],
    choices: [{ label: "Te relever, et faire face à Ardhal", big: true, to: "IVD_ardhal" }] },
  IVD_antre_force: { act: "IV", title: "Les rejetons", place: "glacier",
    combat: { title: "Les rejetons de vase", enemies: [{ id: "IVD_rejeton", n: 2 }], terrain: "nature",
      win: { fx: { ep: ["seance", 3000] }, to: "IVD_antre_force_fin" }, lose: { fx: { pv: -6 }, to: "IVD_antre_force_fin" },
      flee: { label: "Reculer jusqu'à l'arche", dom: "nature", diff: -10, to: "IVD_antre_force_fin" } },
    text: [
      "Tu entres l'arme haute. Tu as fait dix pas quand la glace du sol se met à suinter. Des flaques noires sourdent entre les dalles, s'élargissent, se rejoignent, et se lèvent : des formes basses, à quatre pattes, faites de vase et d'éclats d'écailles blanches, qui ont la forme vague de petits dragons, de lézards gros comme des chiens. Elles sortent de lui. Elles coulent de ses flancs, de la patte noire, et viennent vers toi en sifflant.",
    ] },
  IVD_antre_force_fin: { act: "IV", title: "La voix sous la voûte", place: "glacier",
    text: [
      { outcome: "win", text: "La dernière des choses se défait sur la glace en une flaque qui fume, puis qui sèche. Tu as les bras couverts de vase jusqu'aux coudes." },
      { outcome: "lose", text: "Les choses t'ont mordu{e} et griffé{e} avant de fondre d'elles-mêmes, comme si on les avait rappelées." },
      { outcome: "flee", text: "Tu recules jusqu'à l'arche. Les choses ne te suivent pas. Elles retournent vers le fond de la salle, et rentrent dans le flanc de la bête comme de l'eau dans du sable." },
      { if: { is: { gloup: "tue" } }, text: "Tu penses, sans le vouloir, à une petite chose de bave dans une grotte du Rouvre, qui te regardait de ses deux yeux ronds avant que tu frappes. Celles-ci n'avaient pas d'yeux. Ça n'aide pas autant que tu le voudrais." },
      "Au fond de la salle, quelque chose d'immense lève la tête. Un œil pâle, presque blanc. Un œil noir. « Elle t'a vu{e} venir avec une arme, dit une voix très lente, très lasse. Elle se défend. Moi, je n'ai pas encore décidé. Pose ça, ou ne le pose pas. Mais approche. »",
    ],
    choices: [{ label: "Faire face à Ardhal", big: true, to: "IVD_ardhal" }] },
  IVD_antre_vire: { act: "IV", title: "La porte de derrière", place: "glacier",
    fx: { flag: "IVD:ami" },
    text: [
      "La vire monte dans la paroi, à peine large comme un pied, et contourne l'arche par la droite. Tu passes le premier ressaut en te tenant à la roche, puis un deuxième, puis tu arrives à une fente, haute et étroite, d'où sort un souffle tiède. Tu t'y glisses, et tu te retrouves sur une corniche, au-dessus de la grande salle, à hauteur de sa tête.",
      "Il te regarde. Il t'a entendu{e} venir depuis le premier ressaut. Il n'a pas bougé.",
      "« Les Fermaud, dit-il. Il n'y a que les Fermaud qui connaissent ce passage. Je le leur ai laissé, il y a longtemps. Le vieux Fermaud m'apportait des truites quand j'étais malade, l'hiver de la grande neige. » Sa voix est très basse, très lente, et il y a quelque chose dedans qui ressemble à de la tendresse. « Tu viens de leur part. Alors je te reçois comme eux. Même si tu ne leur ressembles pas. »",
    ],
    choices: [{ label: "Faire face à Ardhal", big: true, to: "IVD_ardhal" }] },
  IVD_antre_pip: { act: "IV", title: "La lumière dans l'antre", place: "glacier", with: "pip",
    fx: { flag: "IVD:ami" },
    text: [
      "Pip entre seul dans la grande salle. Tu le regardes s'éloigner, une petite lumière jaune dans tout ce bleu, de plus en plus petite. Il ne va pas vite. Il va droit vers le fond, vers la forme immense, et s'arrête juste devant sa tête.",
      "Le dragon ouvre un œil. L'œil pâle. Il regarde Pip très longtemps, et Pip le regarde aussi, et rien ne bouge. Puis le dragon expire, un long souffle tiède qui fait vaciller la lumière, et il dit, si bas que tu l'entends à peine depuis l'arche : « Oh. C'est toi. »",
      "Pip se tait. Il ne sait pas quoi répondre. Il se retourne vers toi, et sa lumière tremble. « Il me connaît, dit-il. Je ne le connais pas. Viens. »",
    ],
    choices: [{ label: "Rejoindre Pip devant Ardhal", big: true, to: "IVD_ardhal" }] },
  IVD_antre_thavary: { act: "IV", title: "La manière ancienne", place: "glacier", with: "thavary",
    text: [
      "Thavary entre la première, l'épée nue, mais la pointe en bas, la lame couchée sur ses deux paumes ouvertes, comme on la présente à un suzerain. Elle marche au milieu de la salle d'un pas égal, et à vingt pas du fond, elle met un genou en terre sur la glace.",
      "« Thavary de Thavar, dit-elle d'une voix claire qui monte sous la voûte. Fille de Thavar le Fidèle, dernière de sa maison. Je viens payer une dette, si on veut bien me dire laquelle. »",
      "Le repli de roche bouge. Une tête se lève. Un œil pâle, un œil noir. La voix qui sort de la gueule est lente comme une meule. « Thavar, dit le dragon. Thavar le Fidèle. Il avait de la barbe partout et il ronflait. Il pleurait, la dernière nuit. Il n'a pas pleuré le lendemain. » Il regarde Thavary. « Relève-toi, petite. Ce n'est pas toi qui dois. »",
    ],
    choices: [{ label: "Faire face à Ardhal", big: true, to: "IVD_ardhal" }] },
});

// ------------------------------------------------------------------ Ardhal: what he saw, what he asks
Object.assign(P, {
  IVD_ardhal: { act: "IV", title: "Ardhal", place: "glacier", backName: "la grande salle de l'antre",
    fx: { ep: ["histoire", 4000], regard: { ardhal: "curieux" } },
    text: [
      { first: true, if: { not: { has: "IVD:vu_dormir" } }, text: "Il se lève à demi pour te regarder, et il n'en finit pas de se lever. La tête d'abord, longue, étroite, plus grande qu'un cheval, couronnée de cornes qui partent vers l'arrière comme des branches de bois mort. Le cou ensuite, qui se déroule. Puis les épaules, et les ailes repliées contre les flancs comme deux voiles affalées. Ses écailles sont blanches, d'un blanc d'os, d'ivoire jauni, et entre elles, dans chaque jointure, a poussé une matière noire et luisante qui forme des veines. Elles battent. Sa patte avant gauche est noire jusqu'à l'épaule." },
      { first: true, text: "Il sent le froid, la pierre, le vieux fer. Et dessous, faible, l'odeur du bief de Brumefeuille, l'odeur du lac de Morteau, l'odeur de toutes les eaux mortes que tu as croisées depuis l'automne." },
      { first: true, text: "« Je suis Ardhal, dit-il. Tu le sais. Tout le monde le sait, en bas, même ceux qui ne le disent pas. Et toi, qui es-tu, qui montes jusqu'ici à l'entrée de l'hiver, quand même les chasseurs redescendent ? »" },
      { first: true, if: { has: "IVD:ami" }, text: "Il a parlé doucement. Il n'a pas montré les dents. Tu ne sais pas ce que vaut, chez un dragon, le fait de ne pas montrer les dents. Tu crois que ça vaut beaucoup." },
      { first: true, if: { mark: { min: 3 } }, text: "Ses naseaux frémissent. Il te sent, longuement, comme un chien. « Tu sens comme elle, dit-il. Tu portes sa main. » Son œil noir s'est mis à briller. L'œil pâle s'est fermé à demi, comme on ferme les yeux devant une chose qu'on ne veut pas voir." },
      { first: true, if: { all: [{ mark: { max: 0 } }, { has: "eclat:refuse" }] }, text: "Ses naseaux frémissent. « Tu n'as pas sa main sur toi, dit-il. Elle te l'a offerte, et tu l'as refusée. » Il te regarde avec quelque chose qui ressemble à du respect, ou à de la pitié. « Ça a dû te coûter. »" },
      { first: true, if: { is: { jeton: ["ordre", "deux"] } }, text: "« Tu as le fer de l'Ordre dans ta besace, ajoute-t-il. Je le sens d'ici. Ils m'en ont envoyé beaucoup, des gens avec du fer gris. Tu les as vus, en montant, au pied de la moraine. »" },
      { again: true, text: "Ardhal est toujours couché au fond de la salle, la tête posée sur la glace, et il t'écoute. L'œil pâle et l'œil noir te suivent, chacun à sa façon." },
    ],
    choices: [
      { label: "« Tu as connu les Six. Raconte-moi. »", hide: { seen: "IVD_ardhal_six" }, to: "IVD_ardhal_six" },
      { label: "« Et toi ? Tu as laissé faire ? »", hide: { any: [{ not: { seen: "IVD_ardhal_six" } }, { seen: "IVD_ardhal_chaine" }] }, to: "IVD_ardhal_chaine" },
      { label: "« Qu'est-ce qui te ronge ? »", hide: { seen: "IVD_ardhal_voix" }, to: "IVD_ardhal_voix" },
      { label: "« Où est la porte ? »", hide: { seen: "IVD_ardhal_porte" }, to: "IVD_ardhal_porte" },
      { label: "Pip s'approche de son œil pâle", with: "pip", hide: { seen: "IVD_ardhal_pip" }, to: "IVD_ardhal_pip" },
      { label: "Lui montrer les clés du Sceau", hide: { any: [{ seen: "IVD_ardhal_reliques" }, { not: { relics: { min: 1 } } }] }, to: "IVD_ardhal_reliques" },
      { label: "Lui montrer la lettre du chevalier de Valbrune", hide: { any: [{ seen: "IVD_ardhal_chevalier" }, { not: { item: "IVD_lettre_chevalier" } }] }, to: "IVD_ardhal_chevalier" },
      { label: "Lui lire la lettre de ta maîtresse", hide: { any: [{ seen: "IVD_ardhal_lettre" }, { not: { item: "lettre_maitre" } }] }, to: "IVD_ardhal_lettre" },
      { label: "« Et l'homme que tu gardes sous ton aile ? »", hide: { seen: "IVD_ardhal_anthelme" }, to: "IVD_ardhal_anthelme" },
      { label: "Ouvrir le carnet d'Isolde et lui demander ce qu'il faut écrire", hide: { any: [{ seen: "IVD_ardhal_carnet" }, { not: { has: "IVD:promis_cercle" } }] }, to: "IVD_ardhal_carnet" },
      { label: "« Que veux-tu de moi ? »", big: true, to: "IVD_ardhal_demande" },
    ] },
  IVD_ardhal_six: { act: "IV", title: "Ce qu'il a vu", place: "glacier",
    fx: { clue: "IVD_m_ardhal", ep: ["seance", 3000] },
    text: [
      "Il ferme les yeux. Les deux. Quand il parle, sa voix est plus lente encore, comme s'il descendait un escalier très long, marche à marche, dans le noir.",
      "« J'étais jeune. Trois cents ans : c'est jeune, chez nous. Je chassais trop loin, je me battais avec des choses trop grosses. Un été, je suis rentré avec l'aile ouverte de l'épaule à la pointe, et je me suis couché sur ce glacier pour mourir. Un homme est monté. Un garçon, presque. Il avait une besace pleine de pots et de bandes, et il m'a recousu l'aile, avec du fil de lin, pendant trois jours, en me parlant tout le temps pour que je ne m'endorme pas. Il riait trop fort pour un sorcier. Il n'était pas un sorcier. Il avait des mains de guérisseur. »",
      "« L'année d'après, la terre s'est ouverte sous la Fenne. L'eau noire est montée. Il est revenu, avec cinq autres. Un grand roux qui disait qu'il était roi et qui buvait ; une femme sage qui comptait tout ; un barbu qui ronflait et pleurait ; une forgeronne aux bras comme des cuisses ; un moine maigre qui ne dormait jamais. Ils ont campé sur l'éperon. Ils ont parlé toute la nuit. Le matin, le plus jeune est descendu sous la glace, et il a fermé la porte, de l'intérieur, avec son dos. »",
      "Il rouvre l'œil pâle. « Il s'est proposé. Personne ne le lui a demandé. Je veux que tu le saches. Personne. »",
      { with: "thavary", text: "Thavary a baissé la tête au mot de barbu. Elle ne la relève pas." },
      { with: "charline", text: "Charline a dit, très bas, presque pour elle : « Une forgeronne aux bras comme des cuisses. » Elle a l'air de ne pas savoir si elle doit en rire." },
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_chaine: { act: "IV", title: "Ce qu'il a fait", place: "glacier",
    fx: { ep: ["seance", 2500] },
    text: [
      "« J'ai laissé faire, dit-il. Oui. » Il le dit sans attendre, comme quelqu'un qui a eu quatre cents ans pour préparer sa réponse et qui n'en a trouvé aucune de meilleure.",
      "« Les cinq ont eu peur. Ils sont redescendus le soir même, et ils ont parlé entre eux, sur l'éperon, à voix basse, et j'ai tout entendu, parce que j'entends tout. Ils disaient : et s'il lâche ? Et s'il a froid, et s'il a peur, et s'il remonte ? Alors ils ont forgé. La forgeronne a forgé toute la nuit. Le lendemain, ils sont redescendus sous la glace, tous les cinq, et ils l'ont attaché à la porte. Avec trois clés. Il les a laissés faire. Il leur a souri. Je l'ai entendu leur dire que ce n'était pas la peine. Ils l'ont fait quand même. »",
      "« Puis ils sont venus me voir. Ils m'ont demandé de garder la montagne. Que personne ne monte. Que personne ne descende le délivrer. Ils m'ont dit que s'il était délivré, l'eau noire remonterait et que le monde mourrait. C'était vrai. C'est encore vrai, en partie. » Il souffle, longuement. « J'ai dit oui. J'ai gardé. J'ai tué ceux qui montaient. Les pèlerins, les curieux, puis les chevaliers que l'Ordre m'envoyait pour me faire taire. Je ne sais plus, depuis longtemps, si je gardais le monde contre lui ou lui contre le monde. Je sais que je l'entends. Sous la glace. Il ne crie jamais. Il n'a jamais crié. »",
      { with: "aubin", text: "Frère Aubin s'est signé, lentement, puis il a laissé retomber sa main, comme s'il avait honte du geste." },
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_voix: { act: "IV", title: "L'œil noir", place: "glacier",
    fx: { clue: "IVD_v_ardhal", ep: ["seance", 2500] },
    text: [
      "Il tourne la tête pour te montrer l'œil noir. De près, ce n'est pas un œil. C'est une flaque. Une flaque ronde et bombée, enchâssée dans l'orbite, qui reflète la salle, et toi dedans, un peu en retard sur tes gestes.",
      "« L'eau qui coule sous ce glacier vient de la porte, dit-il. Toute l'eau de fonte. Je la bois depuis quatre cents ans. Il n'y en a pas d'autre. Au début, elle avait le goût de la pierre. Puis, il y a cent ans, elle a pris un goût de larmes. Et depuis la Saint-Martin, elle me parle. »",
      "« Elle est douce, dit-il. Elle est raisonnable. Elle me dit que j'ai assez gardé, que je peux dormir, qu'elle gardera à ma place. Elle me dit qu'elle est lui. Elle ne l'est pas. Elle ne parle pas avec sa voix à lui. Elle n'a jamais eu sa voix. Elle a la voix de tous ceux qui ont pleuré au bord d'une eau. »",
      "L'œil noir se plisse. Pendant un instant, une autre voix sort de sa gorge, sous la sienne, une voix de femme : *{hero}.* Il serre les mâchoires, et la voix s'éteint. « Tu vois, dit-il, épuisé. Elle a déjà un œil. Avant la fin de l'hiver, elle aura l'autre. »",
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_porte: { act: "IV", title: "La porte", place: "glacier",
    text: [
      "Il frappe la glace, sous lui, d'une griffe, une seule fois. Le bruit descend, descend, et revient de très loin, longtemps après.",
      "« Je dors dessus, dit-il. Il y a un puits, sous mon ventre, que les cinq ont creusé pour descendre, et qu'ils ont bouché avec de la glace après être remontés. Le puits mène à la porte. La porte mène à lui. Personne n'est descendu depuis quatre cents ans. »",
      "« Je te l'ouvrirai, ou tu l'ouvriras toi-même. Quand tu en auras fini avec moi. Pas avant. On ne descend pas là en laissant derrière soi un dragon qui ne sait pas encore ce qu'il est. »",
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_pip: { act: "IV", title: "La petite lumière", place: "glacier", with: "pip",
    fx: { conf: { pip: 5 }, ep: ["seance", 2500] },
    text: [
      "Pip vole jusqu'à l'œil pâle, et se pose sur le bord de l'orbite, sur les écailles, comme sur une branche. Le dragon reste immobile. Il le regarde de si près qu'il doit loucher.",
      "« Je t'ai vu, dit Ardhal. Il y a longtemps. Tu étais plus chaud, alors. Plus grand. Tu riais. » Il souffle doucement, et Pip vacille. « Tu ne te souviens pas. Ce n'est pas grave. Ce n'est pas à moi de te le dire. »",
      "« Pourquoi pas ? » demande Pip, et sa voix tremble. C'est la première fois que tu l'entends en colère. « Tout le monde sait des choses sur moi, et personne ne me les dit. Pourquoi pas toi ? »",
      "« Parce que ce n'est pas à moi, répète le dragon, avec une patience immense. C'est à celui qui t'a tenu. Il est en bas. S'il peut encore parler, il te le dira. S'il ne peut plus, tu le sauras quand même, en le voyant. » Il ferme l'œil pâle. « Va. Retourne sur cette épaule. Tu es bien, là. »",
      "Pip revient sur ton épaule. Il ne dit plus rien pendant très longtemps, et il brille, tout ce temps, plus fort que tu ne l'as jamais vu briller.",
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_reliques: { act: "IV", title: "Les clés", place: "glacier",
    fx: { ep: ["seance", 2500] },
    text: [
      "Tu poses sur la glace, devant lui, ce que tu portes. Il les regarde sans approcher la tête, comme on regarde des choses qui ont appartenu à des morts.",
      { if: { relic: "clou" }, text: "« Le clou de la forgeronne, dit-il. Elle l'a forgé avec son propre sang dans la trempe. Elle disait que c'était pour que ça tienne. Je crois que c'était pour avoir mal, elle aussi. »" },
      { if: { relic: "cloche" }, text: "« La cloche du moine. Elle n'a pas de battant. Il l'a arraché lui-même, le battant, avec les dents, la nuit avant. Il disait qu'une cloche qui ne sonne que sur la pierre ne pourrait pas appeler au secours. »" },
      { if: { relic: "anneau" }, text: "« L'anneau du barbu. Il le portait à la main gauche. Quand ils sont descendus, il l'a tourné vers l'intérieur de la paume, pour ne plus voir la pierre. »" },
      { if: { relics: { min: 3 } }, text: "Les trois, posés côte à côte sur la glace, se mettent à vibrer. Pas à sonner : à vibrer, d'une note si basse qu'on la sent dans les os plutôt qu'on ne l'entend. Sous la glace, très loin, quelque chose répond, une fois. Le dragon a fermé les yeux. « Elles sont faites pour être ensemble, dit-il. Elles se reconnaissent. Avec elles trois, on peut fermer. On peut aussi laver. C'est la même chose, vu de l'autre côté. »" },
      { if: { any: [{ has: "vole:clou" }, { has: "vole:cloche" }, { has: "vole:anneau" }] }, text: "Tu lui dis aussi qu'on t'en a pris une, dans le défilé de la Gorge-Blanche, une femme aux gants noirs qui croyait bien faire. Il souffle, longuement. « Celle-là aussi descendra, dit-il. Tout ce qu'on vole à cette porte finit par y retourner. »" },
      { if: { given: "clou" }, text: "Tu lui dis que le Clou est resté à la Forge-Mère, que tu l'as rendu. Il incline la tête. « Rendu. Bien. Ce qu'on rend revient toujours, d'une façon ou d'une autre. Ce qu'on garde, on ne sait jamais. »" },
      { if: { given: "cloche" }, text: "Tu lui dis que la Cloche est chez l'Ordre, à la commanderie, et qu'on la bénit chaque matin. « Ils la bénissent, dit-il. C'est bien. Ils devraient lui demander pardon, aussi. »" },
      { if: { given: "anneau" }, text: "Tu lui dis que l'Anneau est retourné chez Dame Ermesinde, à Thavar. « Chez le barbu, dit-il. Bien. Qu'il le porte encore un peu, ce qui reste de lui. »" },
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_chevalier: { act: "IV", title: "Valbrune", place: "glacier",
    fx: { ep: ["seance", 2000] },
    text: [
      "Tu lui lis la lettre de l'Ordre, et ce qui est écrit au dos, au crayon. Il écoute sans bouger.",
      "« Anseric, dit-il. Je me souviens de lui. Il est monté seul, avec cette épée pâle qui ne rouille pas. Il ne m'a pas attaqué. Il s'est assis là où tu es, et il m'a demandé si c'était vrai, ce qu'on disait à Ferrance. Je lui ai tout raconté. Il a pleuré. Puis il est reparti, en courant presque, pour le dire. » Un temps. « La montagne l'a pris dans une crevasse, à une demi-journée d'ici. Ce n'est pas moi. Je te le jure sur l'aile qu'on m'a recousue. C'est la montagne. Elle ne choisit pas. »",
      { if: { item: "IVD_lame_givre" }, text: "Il regarde l'épée pâle à ta ceinture. « Tu l'as prise. Bien. Il aurait voulu qu'elle redescende. »" },
      { if: { has: "passe:ordre" }, text: "Tu as porté le même gant que lui. Tu as gardé des routes pour l'Ordre, trois ans. Ce qu'on demandait à Anseric, on aurait pu te le demander. Tu ne sais pas ce que tu aurais fait." },
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_lettre: { act: "IV", title: "La lettre de ta maîtresse", place: "glacier",
    fx: { ep: ["seance", 2000] },
    text: [
      "Tu lui lis des passages de la lettre, ceux que tu sais par cœur maintenant, à force de les avoir relus. Il écoute. Quand tu t'arrêtes, il ne dit rien pendant un long moment.",
      "« Elle avait compris, dit-il enfin. Toute seule, d'en bas, avec des livres. Elle n'est jamais montée jusqu'ici. Elle aurait dû. Je lui aurais dit le reste. »",
      { if: { is: { maitre: "sauve" } }, text: "Tu lui dis qu'elle est vivante. Qu'elle est à Vaux, sous une tente, et qu'elle guérit lentement. Il incline la tête. « Alors dis-lui de monter, au printemps. S'il y a un printemps. Je lui raconterai. »" },
      { if: { is: { maitre: "mort" } }, text: "Tu lui dis qu'elle est morte. Tu ne lui dis pas comment. Il te regarde, et tu as l'impression qu'il le sait quand même. « Elle a écrit ça avant, dit-il. Avant l'eau. C'est ça qu'il faut garder d'elle. Le reste, c'est l'eau. »" },
      { if: { is: { maitre: "perdu" } }, text: "Tu lui dis que l'eau l'a reprise. Qu'elle s'est enfuie dans l'Isarde. Il ferme l'œil pâle. « Alors tu la reverras, dit-il. En bas. Tout ce que l'eau prend finit en bas. Prépare-toi. »" },
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_anthelme: { act: "IV", title: "Le prêcheur", place: "glacier",
    text: [
      "Il soulève son aile gauche, lentement. Contre son flanc, dans la chaleur de son corps, il y a un homme en robe de prêcheur, couché en rond, les mains jointes sous le menton. Il est mort. Il a l'air de dormir.",
      "« Il est monté il y a trois jours, en chantant, dit le dragon. Il m'a demandé de rendre l'eau claire. Il disait qu'une dame le lui avait promis, dans la glace, s'il venait jusqu'à moi. Je lui ai dit que je ne pouvais pas. Il ne m'a pas cru. Il a prié, toute la nuit, à genoux sur la glace, et il a commencé à geler. Alors je l'ai pris contre moi. Pour qu'il ait chaud. » Il replie l'aile. « Il est mort quand même. Avant-hier. Je l'ai gardé. C'est idiot. Je ne sais pas pourquoi je l'ai gardé. »",
      { if: { has: "pelerins:sort" }, text: "Tu penses aux trente-deux, en bas, à genoux dans la neige, et à celui qui avait une tache de vin sur la main. Tu te tais." },
      { with: "aubin", text: "Aubin s'approche, sans demander, et s'agenouille près de l'aile. Le dragon le laisse faire. Aubin ferme les yeux du prêcheur, et dit les mots, et le dragon écoute les mots avec une attention étrange, comme quelqu'un qui reconnaît une chanson qu'il n'a pas entendue depuis très longtemps." },
    ],
    choices: [{ back: "IVD_ardhal" }] },
  IVD_ardhal_carnet: { act: "IV", title: "Mot pour mot", place: "glacier",
    fx: { fac: { cercle: 10 }, ep: ["seance", 2000], flag: "IVD:carnet_ecrit" },
    text: [
      "Tu ouvres le carnet d'Isolde sur ton genou, tu tailles le crayon de plomb avec ton couteau, et tu lui demandes ce qu'il veut que le Cercle sache.",
      "Il réfléchit très longtemps. Tu as froid aux doigts. « Écris, dit-il enfin. Écris : ils avaient peur. Pas de lui. D'eux-mêmes. Ils avaient peur de ne pas être capables, eux, de faire ce qu'il a fait. Alors ils ont fait en sorte que personne ne le sache jamais. »",
      { if: { has: "passe:cercle" }, text: "Tu écris de ta main de copiste, celle qu'on t'a apprise à l'Athénée, droite et serrée, sans une rature. On t'avait appris à recopier ce que d'autres avaient dit. C'est la première fois que tu écris ce que personne n'a encore jamais écrit." },
      "Tu écris. Il attend que tu aies fini. « Et écris aussi : le dragon dit qu'il a eu peur, lui aussi. Et qu'il a dit oui. » Tu écris. Le crayon casse sur le dernier mot.",
    ],
    choices: [{ back: "IVD_ardhal" }] },

  // the act choice
  IVD_ardhal_demande: { act: "IV", title: "Ce qu'il demande", place: "glacier",
    text: [
      { first: true, text: "Il pose la tête sur la glace, devant toi, si près que tu sens son souffle sur tes jambes. Il est fatigué. Il a parlé plus qu'il ne l'a fait depuis cent ans. Les veines noires de son cou battent plus vite." },
      { again: true, text: "Il pose à nouveau la tête sur la glace, devant toi. Il attend. Il a l'air de quelqu'un qui peut attendre encore un peu, mais pas beaucoup." },
      "« Avant la fin de l'hiver, dit-il, elle aura l'autre œil. Alors je ne serai plus moi. Je descendrai dans vos vallées, et je soufflerai sur vos villages, et vos rivières gèleront avec les gens dedans, et je ne m'en souviendrai pas. Elle s'en souviendra pour moi. »",
      "« Si tu as de quoi me laver, lave-moi. Je ne sais pas si c'est possible. On m'a dit que c'était possible, il y a longtemps, et celui qui me l'a dit savait laver. Sinon, tue-moi. Proprement, de face, comme on tue une bête qu'on respecte. Je me défendrai : elle se défendra, et je ne pourrai pas l'en empêcher. »",
      "Il ouvre l'œil pâle, et le fixe sur toi. « Mais ne me mets pas de chaîne. Ne me lie pas. J'en ai vu mettre une, une fois, à quelqu'un qui ne la méritait pas, et j'ai laissé faire. Ne me fais pas ça. »",
      { if: { mark: { min: 1 } }, text: "Ta main gauche brûle. Sous la glace, sous lui, tu entends l'eau qui fredonne. Elle attend aussi. Elle sait ce que ta main peut faire." },
      { with: "coliane", text: "Coliane a croisé les bras. Elle se tait. Elle te regarde, toi, pas le dragon." },
      { with: "pip", text: "Pip est sur ton épaule. Tu sens sa lumière contre ta joue, tiède, et qui tremble." },
    ],
    choices: [
      { label: "« Je peux te laver. »", big: true,
        if: { any: [{ relics: { min: 3 } }, { all: [{ present: "aubin" }, { loyal: "aubin" }] }, { all: [{ present: "pip" }, { item: "eau_claire" }] }] },
        why: "Il faudrait les trois clés du Sceau en main, ou Frère Aubin à tes côtés et confiant, ou Pip et une fiole d'eau claire.", to: "IVD_purifier" },
      { label: "« Alors je te tuerai, de face. »", big: true, to: "IVD_tuer" },
      { label: "Lui poser ta main sur le front, et le lier", big: true, tag: "Marque +2", stain: true, to: "IVD_lier" },
      { label: "« Attends encore un peu. Je reviens. »", back: "IVD_glacier" },
    ] },
});

// ------------------------------------------------------------------ the view over the Marches (shared by the three outcomes)
var PANO = [
  { if: { has: "grauk:vivant" }, text: "Là-bas, à l'ouest, sur sa crête, le château des trolls : de la fumée monte de ses cheminées rafistolées. Grauk y règne toujours, gros et vieux, et ne descend toujours pas à ses caves.", else: "Là-bas, à l'ouest, sur sa crête, le château des trolls, sans une fumée. Les trolls l'ont quitté après la mort de leur roi. Les corbeaux l'habitent." },
  { if: { has: "durn:marteau" }, text: "Plus bas, aux Trois-Bornes, une étincelle rouge dans le gris : la forge de Durn, qui bat encore, avec son marteau à manche de frêne." },
  { if: { is: { aglae: ["libre", "ramenee"] } }, text: "Et la fumée de la Lanterne éteinte, aux Trois-Bornes. Aglaé a retrouvé une cuisine à elle, quelque part là-dessous, et ne parle jamais des deux hivers d'avant." },
  { if: { has: "puits:clair" }, text: "La Sorbe, en bas, est grise sur toute sa longueur. Sauf autour de Brumefeuille, où une tache d'eau claire s'obstine : le puits que tu as rendu, et que la souillure contourne comme un caillou dans un courant.", else: "La Sorbe, en bas, est grise sur toute sa longueur, et Brumefeuille, au bord des marais, n'est plus qu'un amas de toits sans fumée." },
  { if: { is: { berthe: "pendue" } }, text: "Au bord de l'eau, la petite maison de Berthe a perdu son toit. Personne ne l'a reprise." },
  { if: { given: "clou" }, text: "Au nord, sous sa fumée éternelle, Ferrance. La Forge-Mère y garde le Clou de Hildre, et ses feux, vus d'ici, font une lueur rouge sous les nuages." },
  { if: { given: "cloche" }, text: "La tour carrée de la commanderie, dans le Val d'Anse, où l'on bénit chaque matin une cloche sans battant." },
  { if: { given: "anneau" }, text: "Le verger de Thavar, et ses toits qu'on a commencé à réparer. Une vieille femme y garde un anneau dans un coffret, avec une lettre." },
  { if: { has: "merle:sauve" }, text: "Au sud, l'Isarde, gelée sur ses bords, et Merle-sur-Isarde, ses toits rebâtis, son église de pierre. Merle tient.", else: "Au sud, l'Isarde, gelée sur ses bords, et ce qui reste de Merle-sur-Isarde : une église de pierre au milieu des cendres, et des barques renversées sur la grève." },
  { if: { is: { couronne: "paix" } }, text: "Les deux camps de l'Isarde sont vides. Les tentes bleues et les tentes pourpres sont parties chacune chez elles, et le gué n'est plus qu'un gué." },
  { if: { is: { couronne: "aldaran" } }, text: "Sur la rive sud de l'Isarde, des bannières bleues à la tour d'argent flottent sur ce qui était les terres de Vel-Orin." },
  { if: { is: { couronne: "velorin" } }, text: "Sur la rive nord de l'Isarde, des bannières pourpres au croissant d'or flottent jusqu'aux portes de Hautmont." },
  "Et tout près, au pied de la Fenne, le camp de Vaux-Saint-Pierre, ses feux, ses tentes, ses milliers de gens qui ont marché jusqu'ici parce qu'il n'y avait plus d'eau ailleurs. D'ici, on dirait une poignée de braises jetée sur la neige.",
];

